function normalizeChronology(state){if(!state?.hero)return state;state.hero.age=28;const fix=text=>typeof text==='string'?text.replace('Влад вернулся спустя двенадцать лет.','Влад вернулся спустя двадцать лет, в возрасте двадцати восьми.').replace('Проходит двенадцать лет. Влад возвращается к родным местам.','Проходит двадцать лет. Владу двадцать восемь. Он возвращается к родным местам.').replace('От той ночи до возвращения домой прошло двенадцать лет.','После ухода от Феофана прошло двенадцать лет. Теперь Владу двадцать восемь.'):text;state.journal=(state.journal||[]).map(fix);for(const entry of state.ui?.novelHistory||[])entry.text=fix(entry.text);for(const slot of state.saves||[])if(slot?.snapshot)normalizeChronology(slot.snapshot);return state}
function hydrateState(saved){const defaults=initial();function merge(base,value){if(Array.isArray(base))return Array.isArray(value)?value:base;if(base&&typeof base==='object'){const out=value&&typeof value==='object'&&!Array.isArray(value)?{...value}:{};for(const key of Object.keys(base))out[key]=merge(base[key],out[key]);return out}return value===undefined||value===null?base:value}const restored=merge(defaults,saved);if(!['day','event','outcome','combat','waveDialogue','defeat'].includes(restored.phase))restored.phase='day';return normalizeChronology(restored)}
function restorePhaseModal(){if(game.screen!=='game'||game.ui.openModal)return;if(game.phase==='defeat'){game.ui.openModal={type:'defenseDefeat'};return}if(game.phase==='event')game.ui.openModal={type:'night'};else if(game.phase==='outcome')game.ui.openModal={type:'outcome',...(game.ui.outcome||{title:'Ночь завершена',text:'Результаты уже учтены. Можно встретить рассвет.',lines:[]})};}
let game;try{const s=JSON.parse(localStorage.getItem('shadow-tale-game')||'null');game=s&&s.hero&&s.resources?hydrateState(s):initial()}catch{game=initial()}game.screen='loading';game.ui.openModal=null;game.ui.loadingProgress=0;game.dialogueNotes??=[];game.ui.diaryPage??=0;game.ui.mapSelection??='village';game.settings.keys={...baseSettings().keys,...(game.settings.keys||{})};if(!game.ui.savesMigrated){const old=Array.isArray(game.saves)?game.saves:[],activeSlot=Number.isInteger(game.ui.activeSaveSlot)?old[game.ui.activeSaveSlot]:null;game.saves=old.filter(x=>x&&x.snapshot).sort((a,b)=>(b.timestamp||0)-(a.timestamp||0)).slice(0,3);while(game.saves.length<3)game.saves.push(null);game.saves.forEach((x,i)=>{if(x){x.slotId=i;x.name??=`Выселки · День ${x.day}`}});if(activeSlot)game.ui.activeSaveSlot=game.saves.indexOf(activeSlot);game.ui.savesMigrated=true}game.ui.selectedSave=Math.min(2,Math.max(0,game.ui.selectedSave||0));let loadingIntroStarted=false,loadingTimer=null,loadingCompleteTimer=null,prologueTimer=null,typingTimer=null,autoTimer=null,toastTimer=null,toastQueue=[],questTimer=null;
let storageWarningShown=false;const saveLocal=()=>{try{oakBestiary();refreshActiveSave();localStorage.setItem('shadow-tale-game',JSON.stringify(game));storageWarningShown=false}catch{if(!storageWarningShown){storageWarningShown=true;setTimeout(()=>notify('Не удалось сохранить прогресс в браузере. Проверь доступное место и разрешение на хранение данных.','error'),0)}}};
function playUiTone(kind='tap'){window.storyAudio?.ui();if(kind==='build')window.storyAudio?.action('build')}
function notify(text,kind='minor'){if(toastQueue.some(item=>item.text===text))return;toastQueue.push({text,kind});if(toastTimer)return;function next(){let message=toastQueue.shift();if(!message){toastEl.classList.remove('show');toastTimer=null;return}toastEl.textContent=message.text;toastEl.dataset.kind=message.kind;toastEl.classList.add('show');toastTimer=setTimeout(next,message.kind==='major'?3600:message.kind==='error'?2800:1900)}next()}
function pulseResource(k,delta){if(game.screen!=='game')return;let node=document.querySelector(`[data-resource="${k}"]`);if(!node)return;node.classList.remove('resource-pulse');void node.offsetWidth;node.classList.add('resource-pulse');let mark=document.createElement('em');mark.className='resource-delta '+(delta<0?'negative':'positive');mark.textContent=(delta>0?'+':'')+delta;node.appendChild(mark);setTimeout(()=>{mark.remove();node.classList.remove('resource-pulse')},1500)}
