const loadTips=['Тихий дом лучше слышит домового.','Оберег хранят у порога.','Туман скрывает и путника, и врага.','Лес помнит тех, кто прислушивается.'];
function loadingView(){return `<div class="loading-night"><div class="load-fog fog-a"></div><div class="load-fog fog-b"></div><div class="load-embers" aria-hidden="true"></div><div class="load-center"><div id="animated-logo" class="animated-logo" aria-hidden="true"><img src="assets/game-logo.svg" alt="Сказание о Тени"></div><h1 class="sr-only">Сказание о Тени</h1><div class="load-details"><p class="load-tip" id="load-tip"><span class="eyebrow">Примета</span>${loadTips[0]}</p><div class="load-progress-group"><span class="eyebrow" id="load-stage">${loadLabels[0]}</span><div class="progress"><canvas class="charm-burn" data-charm="burn" aria-hidden="true"></canvas></div></div></div></div></div>`}
