function airyText(text,fraction=0){const words=text.match(/\S+\s*/g)||[];let total=0;const beats=words.map(word=>{const at=total;total+=word.length+(/[.!?…][»”]?\s*$/.test(word)?22:/[,;:—]\s*$/.test(word)?10:0);return {word,at}});return beats.map(({word,at})=>`<span class="airy-word ${fraction>=1||at/total<fraction?'is-visible':''}" data-beat="${at/total}">${esc(word.trimEnd())}</span>${esc(word.slice(word.trimEnd().length))}`).join('')}
