function memoryKnown(s=game){return s.story?.churchMemoryCompleted===true}
const MEMORY_NOTES=[
{id:'memory-home',title:'Два родных места',hint:'Воспоминание у церкви',place:'Выселки и дом Феофана',image:'memory-present-church.png',lead:'Я вернулся в деревню, где жил с мамой и отцом. После той ночи Феофан забрал меня в другое место и вырастил при другой церкви. Нынешние развалины только напомнили о том доме.',aside:'Деревня родителей и дом Феофана — разные места.',question:'Что случилось с деревней за время моего отсутствия?'},
{id:'memory-childhood',title:'Жизнь у Феофана',hint:'Детство после той ночи',place:'Другой дом',image:'memory-church-reading.png',lead:'Феофан учил меня читать и посылал помогать соседям. О том, что я видел в лесу, говорил только: «Когда придёт время». Потом в деревне остановился богатырь и помог отбиться от разбойников. Я решил научиться драться, чтобы больше не быть беспомощным.',aside:'В шестнадцать я ушёл. Феофан отдал мне старый плащ.',question:'Почему он не хотел говорить о той ночи?'},
{id:'memory-service',title:'Дороги и служба',hint:'До возвращения домой',place:'Чужие земли',image:'memory-years-service.png',lead:'Я ходил в походы, служил за плату, защищал заставы. Стал хорошим бойцом, но богатырём себя не считал. После ухода от Феофана прошло двенадцать лет. Теперь мне двадцать восемь. С той ночи в родной деревне минуло двадцать лет.',aside:'Сила не дала ответа на то, что случилось в детстве.',question:'Смогу ли я защитить людей от того, чего ещё не понимаю?'},
{id:'memory-voice',title:'Тень и Голос',hint:'Обряд на лесной поляне',place:'Место боя с культистами',image:'memory-voice-awakening.png',lead:'Во время боя культисты пытались закончить обряд. Из леса пришла Тень. Я узнал тот же холод, что чувствовал ребёнком, и потерял сознание. Очнулся один и впервые услышал Голос. Он сказал, что сам пока не знает, кто он.',aside:'Голос никто не показывал мне. Я только слышал его.',question:'Кто он и почему заговорил именно со мной?'},
{id:'memory-evidence',title:'Знак и промокшее письмо',hint:'Причина возвращения',place:'На поляне после боя',image:'memory-sign-letter.png',lead:'На металлическом знаке был символ с моей детской деревянной птицы. В промокшем письме разобрал лишь «…мальчик…», «…жив…», «…Феофан…» и название деревни родителей. После этого я пошёл обратно туда, откуда меня забрали ребёнком.',aside:'Связь есть, но я ещё не знаю, что она означает.',question:'Почему у культистов был этот знак и зачем они писали обо мне?'}
];
function memoryNotes(){return memoryKnown()?MEMORY_NOTES:[]}
function chronicleContent(){return `<div class="profile-embedded"><h2 class="subhead">Летопись</h2>${window.ProgressLinks?progressLinksView():''}${memoryNotes().map(n=>`<article class="panel section-panel"><h3 class="subhead">${esc(n.title)}</h3><p>${esc(n.lead)}</p><button class="ghost" data-action="diarySelectMemory" data-id="${n.id}">Открыть запись в дневнике</button></article>`).join('')}<div class="ledger">${game.journal.map(x=>`<p>${esc(x)}</p>`).join('')}</div><button class="button" data-action="saves">Открыть сохранения</button></div>`}

const OAK_LINES=[{speaker:'Дуб с цепями',bg:'oak-conversation.webp',text:'Спрашивай. О деревне. О лесе. О том, что осталось под ногами. Я скажу, что чувствую. Чужого знать не могу.'}];
const OAK_TOPICS=[{id:'village',text:'Что случилось с деревней?',icon:82},{id:'church',text:'Что ты знаешь о старой церкви?',icon:103},{id:'forest',text:'Кто живёт в этом лесу?',icon:106},{id:'oak',text:'Расскажи о себе.',icon:82}];
function beginOakEncounter(){if(game.screen!=='game'||game.phase!=='day'||game.ui.openModal||game.ui.oakEncounterActive)return;game.story.oakEncounterSeen=true;game.ui.oakEncounterActive=true;game.ui.oakEncounterIndex=0;game.ui.oakEncounterShown=0;game.ui.placing=null;render()}
function oakEncounterView(){if(!game.ui.oakEncounterActive||game.screen!=='game')return '';const line=window.OAK_ENCOUNTER[Math.min(game.ui.oakEncounterIndex||0,window.OAK_ENCOUNTER.length-1)],role=line.speaker==='Голос'?'voice':'hero';return `<div class="oak-encounter-layer"><div class="dialogue-wrap"><div class="dialogue-box voice-${role}" role="dialog" aria-label="${esc(line.speaker)}"><span class="speaker">${speakerMark(line.speaker)}<span>${esc(line.speaker)}</span></span><p id="oak-encounter-text" class="dialogue-text">${airyText(line.text,(game.ui.oakEncounterShown||0)/line.text.length)}</p><div class="dialogue-footer"><button class="ghost" data-action="oakEncounterLater">Позже</button><button class="button" data-action="oakEncounterNext">${game.ui.oakEncounterIndex===window.OAK_ENCOUNTER.length-1?'Осмотреть дуб':'Далее'}</button></div></div></div></div>`}
function runOakEncounter(){clearInterval(typingTimer);if(game.screen!=='game'||!game.ui.oakEncounterActive||game.ui.openModal)return;const line=window.OAK_ENCOUNTER[game.ui.oakEncounterIndex||0];typingTimer=setInterval(()=>{if(game.screen!=='game'||!game.ui.oakEncounterActive){clearInterval(typingTimer);return}game.ui.oakEncounterShown=Math.min(line.text.length,(game.ui.oakEncounterShown||0)+Math.max(1,game.settings.textSpeed));revealAiry($('#oak-encounter-text'),game.ui.oakEncounterShown/line.text.length);if(game.ui.oakEncounterShown>=line.text.length){clearInterval(typingTimer);typingTimer=null}},25)}
function nextOakEncounter(){if(!game.ui.oakEncounterActive)return;const line=window.OAK_ENCOUNTER[game.ui.oakEncounterIndex||0];if(game.ui.oakEncounterShown<line.text.length){game.ui.oakEncounterShown=line.text.length;render();return}if(game.ui.oakEncounterIndex<window.OAK_ENCOUNTER.length-1){game.ui.oakEncounterIndex++;game.ui.oakEncounterShown=0;render();return}endOakEncounter(true)}
function endOakEncounter(completed=false){if(completed){game.story.oakEncounterCompleted=true;const note='Голос обратил внимание Влада на Дуб, которого он не помнит в деревне детства.';if(!game.journal.includes(note))game.journal.push(note)}clearInterval(typingTimer);typingTimer=null;game.ui.oakEncounterActive=false;render()}
function recordOakSign(){if(game.story.oakRootKnown)return;game.story.oakRootKnown=true;game.story.oakRootDay=game.day;recordStoryEvent('oak-sign','oak-root-sign.webp','Знак на корне Дуба');const note='На корне дуба вырезан знак с моей деревянной птицы. Здесь птицу перечёркивает вертикальная черта. Этого дерева в моём детстве не было. Откуда оно знает наш знак?';game.journal.push(note);if(!game.hero.bag.some(i=>i.itemId==='Деревянная птица'))game.hero.bag.push({itemId:'Деревянная птица',qty:1,storyItem:true})}
function recordOakKnowledge(line){if(!line.oakFact)return;game.story.oakFacts??=[];if(game.story.oakFacts.includes(line.oakFact))return;game.story.oakFacts.push(line.oakFact);const text={'child-target':'Со слов Дуба: лесные существа ищут конкретного ребёнка, а не саму деревню. Кто этот ребёнок — пока неизвестно.','forest-fear':'Со слов Дуба: лес считает ребёнка источником будущего зла и верит, что защищает себя. Это убеждение леса, не доказательство.'}[line.oakFact];if(text)game.journal.push(text)}
function oakBestiary(){const notes=game.dialogueNotes.filter(n=>n.villagerId==='ancient_oak'),known=game.story.oakRootKnown||game.story.oakFirstCompleted||notes.length>0;game.bestiary.ancient_oak={discovered:!!known,notes:Math.min(3,(game.story.oakRootKnown?1:0)+(game.story.oakFirstCompleted?1:0)+(game.story.oakFacts?.length?1:0))};const desc=['Дерево, которого Влад не помнит в своей деревне. На корне — семейный знак птицы, пересечённый вертикальной чертой.'];if(game.story.oakFirstCompleted)desc.push('По его словам, вырос после трагедии: горе пустило корни. Чувствует раненую землю, движение и старые захоронения. Не считает себя частью Тьмы.');if(game.story.oakFacts?.includes('child-target'))desc.push('Говорит, что лесные существа охотятся за ребёнком.');if(game.story.oakFacts?.includes('forest-fear'))desc.push('Лес считает ребёнка будущей угрозой. Дуб различает страх леса и то, что действительно произойдёт.');const battle=window.BattleNarrative?.knowledge(game,'ancient_oak');if(battle)desc.push(battle);return desc.join(' ')}
function oakNotes(){const notes=[];const facts=game.story.oakFacts||[];if(facts.length)notes.push({id:'note:oak-wave-2',title:'Кого боится лес',hint:'После второй ночи',place:'Дуб у Выселок',image:'oak-conversation.webp',lead:'По словам Дуба, лесным существам нужна не деревня, а конкретный ребёнок.'+(facts.includes('forest-fear')?' Лес видит в нём источник будущего зла и считает нападения защитой. Это страх леса, а не доказательство.':''),aside:'Со слов Дуба. Не принимать его рассказ за подтверждение будущего.',question:'Кто этот ребёнок, где он и почему лес его боится?'});if(game.story.oakEncounterCompleted)notes.push({id:'oak-encounter',title:'Дерево, которого я не помню',hint:'Первый подход к Дубу',place:'Выселки',image:'oak-conversation.webp',lead:window.OAK_ENCOUNTER.map(l=>l.speaker+': '+l.text).join(' '),aside:'Голос заметил Дуб у лесной кромки.',question:'Откуда здесь это дерево?'});if(game.story.oakRootKnown)notes.push({id:'oak-sign',title:'Перечёркнутая птица',hint:'Знак на корне',place:'Дуб у Выселок',image:'oak-root-sign.webp',lead:'На корне дуба — почти тот же знак, что на моей деревянной птице. Только птица перечёркнута вертикальной линией. В детстве этого дерева здесь не было.',aside:'Игрушка всё это время оставалась со мной.',question:'Почему семейный знак оказался на новом дереве?'});if(game.story.oakFirstCompleted)notes.push({id:'note:oak-first',title:'Горе пустило корни',hint:'Первый разговор с дубом',place:'Дуб у Выселок',image:'oak-buried-memory.webp',lead:'Дуб появился после огня и крика. По его словам, неизвестные люди приходили ночью не один раз: копали, жгли и что-то закапывали. Что именно — он не сказал. Горе пустило корни, а дуб остался там, где земля болит.',aside:'Дуб не считает себя частью Тьмы. Он чувствует движение земли и старые захоронения.',question:'Что они оставили в земле — и почему дуб узнал меня?'});return notes}
function beginOakTalk(){if(game.screen!=='game'||game.phase!=='day'||!game.ui.sessionStarted||game.ui.memoryActive||game.ui.oakEncounterActive||!window.village3D?.canTalkOak?.())return;game.ui.oakCheckpoint={novelIndex:game.ui.novelIndex,novelChoice:game.ui.novelChoice,novelHistory:game.ui.novelHistory,textShown:game.ui.textShown,novelAuto:game.ui.novelAuto};game.ui.oakActive=true;game.ui.oakMode=game.story.oakFirstCompleted?'hub':'first';game.ui.oakTopic=null;game.ui.novelIndex=game.ui.oakMode==='first'?Math.max(0,Math.min(window.OAK_FIRST_LINES.length-1,game.story.oakFirstIndex||0)):0;game.ui.novelAuto=false;game.ui.textShown=0;game.ui.openModal=null;lastNovelBg='';go('novel')}
function finishOakTalk(completed=false){if(!game.ui.oakActive)return;if(game.ui.oakMode==='first'&&completed){if(!game.story.oakFirstCompleted){recordOakSign();game.story.oakFirstCompleted=true;game.story.oakFirstDay=game.day;recordStoryEvent('oak-first','oak-buried-memory.webp','Горе пустило корни · разговор записан');const text='Дуб вырос после трагедии. Он помнит ночные раскопки и неизвестное, погребённое в земле. Не считает себя частью Тьмы и чувствует места, где земля болит. Почему на его корне семейный знак Влада — пока неизвестно.';game.dialogueNotes.push({id:'oak-first',villagerId:'ancient_oak',speaker:'Дуб с цепями',title:'Горе пустило корни',text,place:'Выселки',day:game.day});game.journal.push('Первый разговор с дубом. '+text)}game.ui.oakMode='hub';game.ui.novelIndex=0;game.ui.textShown=0;lastNovelBg='';render();notify('Разговор с дубом записан в дневнике');return}if(game.ui.oakMode==='first')game.story.oakFirstIndex=game.ui.novelIndex;game.ui.oakActive=false;delete game.ui.oakMode;if(game.ui.oakCheckpoint)Object.assign(game.ui,game.ui.oakCheckpoint);delete game.ui.oakCheckpoint;delete game.ui.oakTopic;lastNovelBg='';go('game')}
function oakTalkView(){const text=OAK_LINES[0].text;return `${bg('oak-conversation.webp','oak-story-art')}<div class="novel oak-novel"><div class="novel-top"><button class="ghost story-skip" data-action="oakReturn">Вернуться в деревню</button></div><div class="dialogue-wrap"><div class="dialogue-box voice-oak"><span class="speaker">${brand(106)}<span>Дуб с цепями</span></span><p class="dialogue-text" id="novel-text">${airyText(text,game.ui.textShown/text.length)}</p></div><div class="dialogue-choices" style="--oak-topic-count:${OAK_TOPICS.length+readyWaveTopics('oak').length}">${[...OAK_TOPICS.map(t=>({...t,locked:true})),...readyWaveTopics('oak').map(t=>({...t,text:window.WAVE_CONTENT.oak[t.wave].title||'После волны '+t.wave,icon:106,waveTopic:true}))].map(t=>`<button class="ghost ${game.ui.oakTopic===t.id?'is-selected':''}" ${t.locked?'disabled title="Тема пока не открыта"':''} data-action="${t.waveTopic?'oakWaveTalk':'oakTopic'}" data-id="${t.id}" aria-pressed="${game.ui.oakTopic===t.id}"><span class="choice-icon">${brand(t.icon)}</span><span class="choice-copy"><span>${esc(t.text)}</span></span></button>`).join('')}</div></div></div>`}

function beginChurchMemory(){if(window.VillageProgress&&!window.VillageProgress.repairCount(game,'chapel')){notify('Сначала восстанови церковь.','error');return;}if(!game.ui.sessionStarted||game.phase!=='day'||game.story.churchMemoryCompleted||!game.story.churchMemoryAvailable)return;migrateChurchMemory();game.ui.memoryCheckpoint={novelIndex:game.ui.novelIndex,novelChoice:game.ui.novelChoice,novelHistory:game.ui.novelHistory,textShown:game.ui.textShown,novelAuto:game.ui.novelAuto};game.ui.memoryActive=true;game.ui.memorySkipped=false;game.ui.novelIndex=game.ui.memoryIndex||0;game.ui.novelHistory=[];game.ui.textShown=0;game.ui.novelAuto=false;lastNovelBg='';go('novel')}
function finishChurchMemory(){if(!game.ui.memoryActive)return;const viewed=!game.ui.memorySkipped;game.story.churchMemoryCompleted=viewed;game.story.churchMemoryAvailable=!viewed;game.ui.memoryActive=false;game.ui.memoryIndex=0;const checkpoint=game.ui.memoryCheckpoint;if(checkpoint)Object.assign(game.ui,checkpoint);delete game.ui.memoryCheckpoint;delete game.ui.memorySkipped;if(viewed){game.story.churchMemoryDay??=game.day;recordStoryEvent('church-memory','memory-present-church.png','Прошлое Влада записано');const summary='Воспоминание у разрушенной церкви: родная деревня Влада и дом Феофана — разные места. После обряда на службе Влад вновь встретил Тень, услышал Голос и нашёл знак и письмо, которые привели его домой.';if(!game.journal.includes(summary))game.journal.push(summary);game.ui.diarySelection='memory-home'}lastNovelBg='';go('game');if(viewed)notify('Воспоминание записано в дневнике и Летописи','action')}

function novelText(){if(game.ui.oakActive&&game.ui.oakMode!=='first')return OAK_LINES[0].text;const line=novelLines()[game.ui.novelIndex];if(!game.ui.ritualMemoryActive&&!game.ui.memoryActive&&!game.ui.oakActive&&!defenseNovelActive()&&!game.ui.waveTalk&&game.ui.novelIndex===novelLines().length-1&&Number.isInteger(game.ui.novelChoice)){return `${['Сначала я услышу людей.','Сначала проверю дорогу.','Сначала встречу ночь во всеоружии.'][game.ui.novelChoice]} ${line.text}`}return line.text}
function novelView(){if(game.ui.oakActive&&game.ui.oakMode!=='first')return oakTalkView();const line=novelLines()[game.ui.novelIndex],text=novelText(),choice=!!line.choices&&game.ui.novelChoice===null&&game.ui.textShown>=text.length,isLast=game.ui.novelIndex===novelLines().length-1;const newArt=line.bg!==lastNovelBg;lastNovelBg=line.bg;if(line.intro)return `${bg(line.bg,'prologue-art story-art-enter')}<div class="cinematic memory-intro"><div class="cinematic-top"><div class="cinematic-actions"><button class="ghost" data-action="novelAuto">Авто: ${game.ui.novelAuto?'вкл':'выкл'}</button><button class="ghost story-skip" data-action="novelSkip">${brand(72)} Пропустить</button></div></div><div class="cinematic-bottom"><h1>${esc(line.title)}</h1><p id="novel-text">${airyText(text,game.ui.textShown/text.length)}</p><div class="row"><button class="button" data-action="novelNext">${game.ui.novelIndex===1?'Вспомнить':'Далее'}</button></div></div></div>`;const roles={'Рассказчик':'narrator','Мать':'mother','Отец':'father','Пришедший':'intruder','Влад':'hero','Отец Феофан':'feofan','Влад · про себя':'hero','Голос':'voice','Тьма':'shadow','Леший':'leshy','Дуб с цепями':'oak','Старший культист':'intruder','Молодой культист':'intruder'};return `${bg(line.bg,newArt?'story-art-enter':'')}<div class="novel">${defenseNovelActive()?'<span class="prototype-story-label">Прототип · сюжетные реплики будут заменены</span>':''}<div class="novel-top"><div class="novel-controls"><button class="ghost" data-action="novelAuto">Авто: ${game.ui.novelAuto?'вкл':'выкл'}</button></div><button class="ghost story-skip" data-action="novelSkip">${game.ui.ritualMemoryActive||game.ui.oakActive||game.ui.waveTalk?.source==='oak'?'Вернуться в деревню':brand(72)+' Пропустить'}</button></div><div class="dialogue-wrap ${text.length<=75&&!line.choices?'is-short':''}"><div class="dialogue-box voice-${roles[line.speaker]||game.villagers.find(v=>v.name===line.speaker)?.id||'narrator'}"><span class="speaker">${speakerMark(line.speaker)}<span>${esc(line.speaker)}</span></span><p class="dialogue-text" id="novel-text">${airyText(text,game.ui.textShown/text.length)}</p>${choice?'':`<div class="dialogue-footer"><button class="button" data-action="novelNext">${isLast?(game.ui.oakActive?'Выбрать тему':game.ui.memoryActive?'Вернуться домой':defenseNovelActive()?'К итогам ночи':game.ui.waveTalk?'Завершить разговор':'В деревню'):'Далее'}</button></div>`}</div>${choice?`<div class="dialogue-choices">${line.choices.map((c,i)=>`<button class="ghost" data-action="novelChoice" data-id="${i}"><span class="choice-icon"><span class="choice-symbol" style="--choice-art:url('icons/${['brand-82','brand-106','brand-103'][i]}.svg')" aria-hidden="true"></span></span><span class="choice-copy"><span>${esc(c)}</span><small>${esc(line.choiceHints[i])}</small></span></button>`).join('')}</div>`:''}</div></div>`}
function runTyping(){clearInterval(typingTimer);clearTimeout(autoTimer);if(game.ui.openModal)return;const text=novelText();if(game.ui.textShown<text.length){typingTimer=setInterval(()=>{game.ui.textShown=Math.min(text.length,game.ui.textShown+Math.max(1,game.settings.textSpeed));const e=$('#novel-text');revealAiry(e,game.ui.textShown/text.length);if(game.ui.textShown>=text.length){clearInterval(typingTimer);typingTimer=null;if(game.ui.novelIndex===novelChoiceIndex())render();else queueAuto()}},25)}else queueAuto()}
function queueAuto(){clearTimeout(autoTimer);if(game.ui.novelAuto&&game.ui.novelIndex<novelLines().length-1&&game.ui.novelIndex!==novelChoiceIndex()&&!game.ui.openModal)autoTimer=setTimeout(nextNovel,5000)}
function nextNovel(){if(game.ui.oakActive&&game.ui.oakMode!=='first'){if(game.ui.textShown<OAK_LINES[0].text.length){game.ui.textShown=OAK_LINES[0].text.length;render()}else finishOakTalk();return}const text=novelText();if(game.ui.textShown<text.length){game.ui.textShown=text.length;const e=$('#novel-text');revealAiry(e,1);clearInterval(typingTimer);typingTimer=null;if(game.ui.novelIndex===novelChoiceIndex())render();else queueAuto();return}if(game.ui.novelIndex===novelChoiceIndex()&&game.ui.novelChoice===null)return;recordOakKnowledge(novelLines()[game.ui.novelIndex]);if(game.ui.novelIndex>=novelLines().length-1){if(game.ui.oakActive)finishOakTalk(true);else if(game.ui.waveTalk)finishWaveConversation();else if(defenseNovelActive())finishDefenseDialogue();else if(game.ui.ritualMemoryActive)finishRitualMemory();else if(game.ui.memoryActive)finishChurchMemory();else enterVillage();return}if(game.ui.oakActive&&novelLines()[game.ui.novelIndex].reveal==='root')recordOakSign();game.ui.novelHistory.push({speaker:novelLines()[game.ui.novelIndex].speaker,text});game.ui.novelIndex++;if(game.ui.oakActive&&game.ui.oakMode==='first')game.story.oakFirstIndex=game.ui.novelIndex;if(game.ui.memoryActive)game.ui.memoryIndex=game.ui.novelIndex;if(game.ui.ritualMemoryActive)game.ui.ritualMemoryIndex=game.ui.novelIndex;game.ui.textShown=0;render()}
function enterVillage(){if(game.ui.sessionStarted)return;game.ui.bottomPanelOpen=false;game.ui.sessionStarted=true;if(game.ui.novelIndex>=LINES.length-1&&game.ui.textShown>=novelText().length)game.ui.novelHistory.push({speaker:LINES.at(-1).speaker,text:novelText()});game.journal.push('В детстве Влад видел Тень после нападения людей, искавших его. Родители исчезли. Феофан велел молчать о той ночи.');if(Number.isInteger(game.ui.novelChoice)){const effects=[{fear:-3,salt:1},{fear:-2,xp:10},{fear:-5,wood:3}];const effect=effects[game.ui.novelChoice];game.fear=Math.max(0,game.fear+effect.fear);if(effect.wood)game.resources.wood+=effect.wood;if(effect.salt)game.resources.salt+=effect.salt;if(effect.xp)game.hero.xp+=effect.xp;game.journal.push('Первый шаг в Выселках: '+LINES[NOVEL_CHOICE_INDEX].choices[game.ui.novelChoice]+'.')}else game.journal.push('Влад вошёл в Выселки, не выбрав, с чего начать.');game.ui.rulesReturn='game';go('rules');notify('День 1 · Выселки')}
const PATHS=[{id:'forest',name:'Лесной дозор',where:'Бор',desc:'Пройти вдоль опушки и вернуться с материалами.',need:0,cost:'Без расхода',reward:'Брёвна +6 · опыт +10'},{id:'marsh',name:'Тропа к топи',where:'Болото',desc:'Найти безопасный ход через туман. Взять с собой соль.',need:1,cost:'Соль −2',reward:'Запись о Болотнике · опыт +25'},{id:'ruins',name:'Старый погост',where:'Погост',desc:'Осмотреть каменную ограду до наступления сумерек.',need:2,cost:'Свечи −2',reward:'Камень +8 · опыт +20'}];
function scoutView(){let used=game.story.scoutedDay===game.day;return `<div class="screen-shell">${screenHead('Разведка',`День ${game.day} · вылазка ${used?'совершена':'доступна'}`,false)}<div class="scout-intro panel"><div><h2 class="subhead">Выбрать тропу</h2><p>Один выход за день. Маршруты открываются после пережитых ночей. Первый шаг Влада отмечен в нитях судьбы.</p></div><span class="pill">${used?'Дозор вернулся':'До сумерек'}</span></div><div class="route-grid">${PATHS.map(p=>{let open=game.ui.nightCount>=p.need,afford=p.id==='marsh'?game.resources.salt>=2:p.id==='ruins'?game.resources.candles>=2:true,visited=game.story.explored.includes(p.id),image={forest:'scout-forest.webp',marsh:'scout-marsh.webp',ruins:'scout-pogost.webp'}[p.id];return `<article class="route-card panel ${open?'':'locked'}"><div class="route-cover"><img src="assets/${image}" alt="${p.where}: пейзаж маршрута" loading="lazy"><span class="route-status icon-leading">${!open?`Откроется после ${p.need} ночи${p.need===1?'и':'ей'}`:visited?brand(110)+' Исследовано':brand(111)+' Неизведано'}</span><span class="route-place">${p.where}</span></div><div class="route-content"><h3>${p.name}</h3><p>${p.desc}</p><div class="route-meta"><div><small>ПРИПАСЫ</small><span>${p.cost}</span></div><div><small>НАХОДКИ</small><span>${p.reward}</span></div></div><button class="button" data-action="scoutPath" data-id="${p.id}" ${used||!open||!afford?'disabled':''}>${used?'Вылазка уже совершена':!open?'Путь скрыт':!afford?'Не хватает припасов':'Отправить дозор'}</button></div></article>`}).join('')}</div></div>`}
const STORY_FINDS=[{name:'Медальон',where:'В заброшенной избе у бора',asset:'medallion',route:'forest'},{name:'Фрагмент иконы',where:'У церкви на погосте',asset:'icon',route:'ruins'},{name:'Обломок колокола',where:'Во дворе церкви',asset:'bell',route:'ruins'},{name:'Красная нить',where:'У тропы через топь',asset:'thread',route:'marsh'}];
function discoverFinds(route,lines=[]){for(const f of STORY_FINDS.filter(f=>f.route===route)){if(game.hero.bag.some(b=>b.itemId===f.name))continue;game.hero.bag.push({itemId:f.name,qty:1});lines.push('Найдено: '+f.name+' · '+f.where)}}
function scoutPath(id){const p=PATHS.find(x=>x.id===id);if(!p||game.story.scoutedDay===game.day||game.ui.nightCount<p.need)return;if(id==='marsh'&&game.resources.salt<2||id==='ruins'&&game.resources.candles<2)return;game.story.scoutedDay=game.day;if(!game.story.explored.includes(id))game.story.explored.push(id);let lines=[];if(id==='forest'){let extra=Math.max(0,game.hero.stats.luck-2);game.resources.wood+=6+extra;gainXp(10);lines.push(`Брёвна +${6+extra}`,'Опыт +10');if(extra)lines.push(`Удача: брёвна +${extra}`)}if(id==='marsh'){game.resources.salt-=2;discoverCreature('bolotnik','scout-marsh');gainXp(25);lines.push('Соль −2','Болотник внесён в бестиарий','Опыт +25');if(game.ui.novelChoice===1){game.fear=Math.max(0,game.fear-4);lines.push('Ты уже изучил окрестности · страх −4')}}if(id==='ruins'){game.resources.candles-=2;game.resources.stone+=8;gainXp(20);lines.push('Свечи −2','Камень +8','Опыт +20')}discoverFinds(id,lines);recordStoryEvent('scout-'+id,({forest:'scout-forest.webp',marsh:'scout-marsh.webp',ruins:'scout-pogost.webp'})[id],p.name);game.journal.push(`Разведка: ${p.name}. ${lines.join(' · ')}.`);autoSave();render();modal('scoutResult',{title:p.name,lines});}
function atlasView(){
 const id=game.ui.mapSelection||'village',p=PATHS.find(x=>x.id===id),open=p&&game.ui.nightCount>=p.need,used=game.story.scoutedDay===game.day,afford=p&&(id==='marsh'?game.resources.salt>=2:id==='ruins'?game.resources.candles>=2:true),choice=game.ui.novelChoice,explored=game.story.explored.includes(id);
 const cover={village:'vyselki.png',forest:'scout-forest.webp',marsh:'scout-marsh.webp',ruins:'scout-pogost.webp'}[id],location=p?p.where:'Выселки',subtitle=p?p.name:'Последний огонь в тумане';
 const pathState=p?(!open?`Откроется после ${p.need} ноч.`:explored?'Исследовано':'Доступно для разведки'):'';
 const fate=[{title:'Та ночь',done:game.ui.sessionStarted,text:'Люди искали восьмилетнего Влада. Тень пришла позже. Родители исчезли, а Феофан велел хранить молчание.'},{title:'Первый шаг',done:Number.isInteger(choice),text:choice==='skipped'?'Влад вошёл в Выселки без плана.':choice===null?'Выбор ещё впереди.':`Влад решил: ${LINES[NOVEL_CHOICE_INDEX].choices[choice].toLowerCase()}.`},{title:'Следующий узел',done:!!game.story.chapterDecision,text:game.story.chapterDecision?game.story.chapterDecision==='guard'?'Выселки укреплены. Люди готовы удержать ночь.':'Начат поиск истока тумана. Следы ведут дальше.':'Следующая сюжетная развилка пока не открыта.'}];
 if(memoryKnown())fate.splice(1,0,{title:'Воспоминание у церкви',done:true,text:'Феофан вырастил Влада в другом месте. Развалины в деревне родителей напомнили о детстве и годах службы.'},{title:'Знак и письмо',done:true,text:'После встречи с Тенью на службе Влад услышал Голос. Символ с детской птицы и письмо с именем Феофана и названием родной деревни привели его домой.'});
 if(window.ProgressLinks)fate.push(...window.ProgressLinks.snapshot(game).nodes);for(const n of oakNotes())fate.push({title:n.title,done:true,text:n.lead});for(const n of waveDiaryNotes())fate.push({title:n.title,done:true,text:n.lead});
 return `<div class="screen-shell atlas-shell"><header class="screen-head"><div><span class="eyebrow">День ${game.day} · ${game.ui.nightCount} ночей пережито</span><h1>Карта и нити судьбы</h1></div><div class="head-nav"><button class="ghost" data-action="village" ${game.ui.sessionStarted?'':'disabled'}>В деревню</button></div></header><div class="atlas-layout"><section class="panel atlas-map"><div class="atlas-map-header"><div><span class="eyebrow">Окрестности Выселок</span><h2>Выбери место на карте</h2></div><span class="atlas-explored">Разведано ${game.story.explored.length} / ${PATHS.length}</span></div><div class="atlas-map-art" role="group" aria-label="Карта окрестностей"><canvas class="charm-thread" data-charm="thread" aria-hidden="true"></canvas><button class="atlas-pin village ${id==='village'?'active':''}" data-action="mapSelect" data-id="village" aria-pressed="${id==='village'}">${brand(109)} <span>Выселки</span></button>${PATHS.map(r=>`<button class="atlas-pin pin-${r.id} ${id===r.id?'active':''} ${game.ui.nightCount<r.need?'unseen':''}" data-action="mapSelect" data-id="${r.id}" aria-pressed="${id===r.id}">${brand(({forest:108,marsh:107,ruins:101})[r.id])} <span>${r.where}</span></button>`).join('')}</div><div class="atlas-legend"><span class="icon-leading">${brand(109)} Дом</span><span class="icon-leading">${brand(111)} Неизведано</span><span class="icon-leading">${brand(110)} Исследовано</span><span class="atlas-legend-tip">Нажми на отметку, чтобы увидеть место</span></div></section><aside class="panel atlas-detail"><div class="atlas-cover"><img src="assets/${cover}" alt="${location}: обложка местности"><span class="atlas-cover-place">${location}</span>${p?`<span class="atlas-cover-status">${pathState}</span>`:''}</div><div class="atlas-detail-body"><h2>${subtitle}</h2><p class="atlas-description">${p?p.desc:'Здесь сходятся сведения жителей, разведанные тропы и решения, которые изменят судьбу деревни.'}</p>${p?`<div class="atlas-facts"><div><small>ПРИПАСЫ</small><strong>${p.cost}</strong></div><div><small>НАХОДКИ</small><strong>${p.reward}</strong></div></div><button class="button atlas-action" data-action="scoutPath" data-id="${p.id}" ${!open||used||!afford?'disabled':''}>${!open?'Тропа ещё скрыта':used?'Дозор уже выходил сегодня':!afford?'Не хватает припасов':'Отправить дозор'}</button>`:`<button class="button atlas-action" data-action="villagers">Поговорить с жителями</button>`}<div class="atlas-threads"><div class="atlas-thread-heading"><span class="eyebrow">Нити судьбы</span><strong>${fate.filter(x=>x.done).length} / ${fate.length} раскрыто</strong></div>${fate.map((f,i)=>`<div class="atlas-thread ${f.done?'revealed':''}"><span class="atlas-thread-node">${brand(f.done?103:102)}</span><div><small>${'Нить '+(i+1)}</small><h3>${f.title}</h3><p>${f.text}</p></div></div>`).join('')}<button class="ghost atlas-journal" data-action="journal">Открыть дневник</button></div></div></aside></div></div>`
}

function chapterView(){return `${bg('vyselki.png')}<div class="chapter-shell"><div class="chapter-panel panel"><span class="eyebrow">После третьего рассвета</span><h1>Куда поведёт нить?</h1><p>Выселки пережили три ночи. Тропа к болоту стала виднее, но деревня остаётся без защиты. Выбери, чему посвятить следующий день.</p><div class="chapter-options"><button class="option" data-action="chapterChoice" data-id="guard"><span class="chapter-choice-icon" style="--choice-art:url('icons/brand-106.svg')" aria-hidden="true"></span><strong>Укрепить Выселки</strong><small>Брёвна +12 · страх −12. Люди почувствуют опору.</small></button><button class="option" data-action="chapterChoice" data-id="search"><span class="chapter-choice-icon" style="--choice-art:url('icons/brand-90.svg')" aria-hidden="true"></span><strong>Искать исток тумана</strong><small>Опыт +35 · откроется запись о Болотнике. Страх +5.</small></button></div><span class="muted small">Прототип: решение сохраняется в Летописи.</span></div></div>`}
function chooseChapter(id){if(game.story.chapterDecision||!['guard','search'].includes(id))return;game.story.chapterDecision=id;recordStoryEvent('chapter-'+id,id==='guard'?'vyselki.png':'scout-marsh.webp',id==='guard'?'Выселки укреплены':'Поиск истока тумана');if(id==='guard'){game.resources.wood+=12;game.fear=Math.max(0,game.fear-12)}else{gainXp(35);game.fear=Math.min(100,game.fear+5);game.bestiary.bolotnik.discovered=true}game.journal.push(id==='guard'?'Решение: укрепить Выселки. Брёвна +12 · страх −12.':'Решение: искать исток тумана. Опыт +35 · страх +5.');go('game');autoSave();notify('Решение записано в Летописи','action')}
function resourceHud(){return Object.entries(RES).map(([k,[name,i]])=>`<div class="res" data-resource="${k}" title="${name}" aria-label="${name}: ${game.resources[k]}">${icon(i)}<span>${game.resources[k]}</span></div>`).join('')}
function gameView(){const questNotice=defenseActive()?null:game.ui.questNotice;let q=(questNotice&&game.quests.find(q=>q.id===questNotice.id))||(defenseActive()?game.quests.find(q=>q.id==='nights'):game.quests.find(q=>!q.done))||null,markers=[['hut','31%','49%'],['well','47%','38%'],['oven','55%','58%'],['tower','69%','27%'],['circle','44%','69%'],['totem','72%','61%']];return `<div class="game"><div id="village-world" class="village-world"></div><div class="village-vignette" aria-hidden="true"></div>${defenseStatus()}<div id="battle-dialogue" class="battle-dialogue" aria-live="polite" aria-atomic="true" hidden></div><div class="village-tools"><button class="ghost scene-time" data-action="sceneTime" ${defenseActive()?'disabled':''} title="Вечер / ночь: освещение без запуска нападения">${brand(81)}${game.ui.sceneTime==='night'?'Ночь':'Вечер'}</button><button class="ghost" data-action="sceneZoomIn" aria-label="Приблизить деревню">+</button><button class="ghost" data-action="sceneZoomOut" aria-label="Отдалить деревню">−</button><button class="ghost" data-action="sceneReset">Общий вид</button></div>${game.ui.placing?`<div class="placement-panel panel"><strong>${esc(BUILD.find(b=>b.id===game.ui.placing)?.name)}</strong><p id="placement-status">Выбери место на земле</p><small>Правая кнопка — установить · R — поворот · Esc — отмена</small><div class="row"><button class="ghost" data-action="placeRotate">Повернуть</button><button class="button" data-action="placeConfirm" disabled>Установить</button><button class="ghost" data-action="placeCancel">Отмена</button></div></div>`:''}<div class="hud-top"><div class="hud-player"><div class="hud-player-row"><button class="hud-card hero-hud" data-action="hero" ${defenseActive()?'disabled':''}><span class="hero-avatar"><img src="assets/bogatyr.png" alt=""></span><div><strong>Влад</strong><span class="hero-level">Уровень ${game.hero.level}</span>${lifeHearts(game.hero.hp,game.hero.hpMax)}</div></button><div class="hud-time" aria-label="День ${game.day}, ${game.phase==='day'?'сумерки':'ночь'}, страх ${game.fear}"><span class="hud-time-icon">${brand(game.phase==='day'?80:81)}</span><strong>День ${game.day}</strong><span>${game.phase==='day'?'Сумерки':'Ночь'}</span><small>Страх ${game.fear}</small></div></div>${q?`<div class="quest-hud ${game.ui.questOpen?'open':''} ${questNotice?'completed':''}"><button class="quest-toggle" data-action="questToggle" aria-expanded="${!!game.ui.questOpen}" aria-label="${game.ui.questOpen?'Свернуть':'Раскрыть'} задание"><span class="quest-indicator">${brand(questNotice?110:111)}</span><span class="quest-label">${questNotice?'Задание выполнено':q.title}</span><span class="quest-chevron">${brand(85)}</span></button><div class="quest-content">${game.phase==='day'&&window.VillageProgress?'<button class="ghost preparation-link" data-action="restoration">План подготовки</button>':''}<strong>${q.title}</strong><small>${questNotice?'Выполнено · ':''}${q.desc} · ${q.progress}/${q.goal}</small><div class="progress"><i style="width:${100*q.progress/q.goal}%"></i></div>${!questNotice&&!defenseActive()?game.quests.filter(t=>!t.done&&t.id!==q.id).map(t=>`<div class="quest-other"><span>${brand(111)}</span><div><strong>${esc(t.title)}</strong><small>${esc(t.desc)}</small></div></div>`).join(''):''}</div></div>`:''}</div><div class="hud-resources"><div class="resource-hud">${resourceHud()}</div><div id="night-tip" class="night-tip" role="status" hidden></div></div><div class="hud-links">${iconButton(game.settings.muted?73:74,game.settings.muted?'Включить звук':'Выключить звук','sound')}${iconButton(76,'Дневник','journal')}${iconButton(75,'Карта и нити судьбы','map')}${iconButton(112,'Жители','villagers')}${iconButton(82,'Разведка','scout')}${iconButton(52,'Настройки','quick')}</div></div>${defenseActive()?equipmentTray():`<div class="bottom-tray ${game.ui.bottomPanelOpen?'':'collapsed'}"><div class="tray-head"><div class="tray-tabs" ${game.ui.bottomPanelOpen?'':'inert'}><button class="ghost ${game.ui.bottomTab==='build'?'active':''}" data-action="trayTab" data-id="build">Постройки</button><button class="ghost" data-action="restoration">Восстановление</button></div><button class="text-button tray-toggle" data-action="trayToggle" aria-expanded="${game.ui.bottomPanelOpen}"><span>${game.ui.bottomPanelOpen?'Свернуть':'Развернуть'}</span>${brand(86)}</button></div><div class="tray-content" ${game.ui.bottomPanelOpen?'':'inert'}><div class="cards">${game.ui.bottomTab!=='market'?BUILD.map(b=>{let ok=canAfford(b.cost);return `<button class="card" data-action="build" data-id="${b.id}" ${ok?'':`disabled title="${missing(b.cost)}"`}><span class="card-art" aria-hidden="true"><img src="assets/card-${b.id}.webp?v=179" alt=""></span><span class="card-copy"><strong>${b.name}</strong><small>${b.desc} · ×${game.buildings[b.id]}</small><span class="cost card-cost">${cardResourceCost(b.cost)}</span></span></button>`}).join(''):MARKET.map(m=>{let ok=game.resources.silver>=m.price;return `<button class="card" data-action="buy" data-id="${m.id}" ${ok?'':'disabled title="Не хватает серебра"'}><span class="card-art" aria-hidden="true"><img src="assets/card-${m.id}.webp" alt=""></span><span class="card-copy"><strong>${RES[m.id][0]} +${m.qty}</strong><small>Для запасов деревни</small><span class="cost card-cost">${cardResourceCost({silver:m.price})}</span></span></button>`}).join('')}</div></div></div>`}<button class="button night-btn" data-action="night" ${game.phase==='day'&&game.defense.completed<3?'':'disabled'}>${defenseActive()?'Идёт нападение':game.defense.completed>=3?'Три волны отражены':window.VillageProgress?.readiness(game).ready?'Начать защиту':'Подготовка к ночи'}</button></div>`}
function screenHead(title,subtitle,showMenu=true){return `<header class="screen-head"><div>${subtitle?`<span class="eyebrow">${subtitle}</span>`:''}<h1>${title}</h1></div><div class="head-nav">${showMenu?'<button class="ghost" data-action="menu">В меню</button>':''}<button class="button" data-action="village" ${game.ui.sessionStarted?'':'disabled title="Сначала начните игру"'}>В деревню</button></div></header>`}
function heroView(){let h=game.hero,t=game.ui.heroTab==='skills'?'stats':game.ui.heroTab,stats=[['str','Сила','Опыт за смелость'],['end','Стойкость','Жизни и защита'],['faith','Вера','Защита от страха'],['luck','Удача','Серебро и разведка']];let detail=t==='stats'?`<div class="eyebrow">Свободных очков: ${h.statPoints}</div>${stats.map(([id,n,sub])=>`<div class="stat-row"><div><strong>${n}</strong><div class="muted small">${sub}</div></div><div class="stat-actions"><span class="small">${h.stats[id]} / 10</span><button class="ghost" data-action="statMinus" data-id="${id}" ${h.allocated[id]?'':'disabled title="Нет вложенных очков"'}>−</button><button class="ghost" data-action="statPlus" data-id="${id}" ${h.statPoints&&h.stats[id]<10?'':'disabled title="Нет очков или достигнут предел"'}>+</button></div></div>`).join('')}<button class="ghost" data-action="resetStats" ${Object.values(h.allocated).some(Boolean)?'':'disabled'}>Сбросить распределение</button><div class="hero-skill-detail"><div class="between"><h3 class="subhead">Умения</h3><span class="eyebrow">Очки: ${h.skillPoints}</span></div>${(()=>{let sk=SKILLS.find(s=>s[0]===game.ui.selectedSkill)||SKILLS[0];return `<div class="hero-skill-picked"><span class="hero-skill-picked-icon">${skillArt(sk[0])}</span><div><strong>${sk[1]}</strong><p>${sk[3]}</p><small>${h.learnedSkills.includes(sk[0])?'Изучено':`Цена: ${sk[2]} оч.`} · Действует ночью</small></div></div><button class="button" data-action="learnSkill" data-id="${sk[0]}" ${h.learnedSkills.includes(sk[0])||h.skillPoints<sk[2]?'disabled':''}>${h.learnedSkills.includes(sk[0])?'Изучено':h.skillPoints<sk[2]?'Не хватает очков':'Изучить'}</button>`})()}</div>`:t==='equipment'?`<div class="equipment-grid">${Object.entries(h.equipment).map(([id,n])=>`<div class="equipment-row"><span class="muted">${{weapon:'Оружие',shield:'Щит',helm:'Шлем',armor:'Доспех',cloak:'Плащ'}[id]}</span><strong class="small">${n}</strong></div>`).join('')}</div>${window.ProgressLinks?progressInventoryView():''}<h3 class="subhead" style="margin-top:26px">Сума</h3><div class="skill-grid">${h.bag.map((b,i)=>b.qty>0?`<button class="skill ${game.ui.selectedItem===i?'active':''}" data-action="selectItem" data-id="${i}">${({'Старый тулуп':105,'Записка':100,'Волчий зуб':99,'Железный гвоздь':98})[b.itemId]?brand(({'Старый тулуп':105,'Записка':100,'Волчий зуб':99,'Железный гвоздь':98})[b.itemId]):icon(b.itemId==='Топор'?47:b.itemId==='Фонарь'?56:b.itemId==='Корень плакун-травы'?60:41)}<h3>${b.itemId} ×${b.qty}</h3></button>`:'').join('')}</div>${(()=>{let b=h.bag[game.ui.selectedItem];return b?.qty>0?`<div class="panel section-panel" style="margin-top:14px"><h3 class="subhead">${b.itemId}</h3><p class="muted small">${b.use==='heal'?'Восстанавливает до 2 сердец':b.slot?'Можно надеть вместо текущего предмета':'Предмет в суме'}</p>${b.slot?`<button class="button" data-action="equip" data-id="${game.ui.selectedItem}">Надеть</button>`:b.use?`<button class="button" data-action="useItem" data-id="${game.ui.selectedItem}" ${h.hp>=h.hpMax?'disabled title="Жизни полны"':''}>Использовать</button>`:''}</div>`:''})()}`:t==='bestiary'?bestiaryContent():`${chronicleContent()}`;
return `<div class="screen-shell">${screenHead('Профиль Влада',`Уровень ${h.level} · опыт ${h.xp}/100`,false)}<div class="hero-profile"><aside class="panel section-panel hero-identity"><div class="detail-image hero-portrait"><img src="assets/bogatyr.png" alt="Влад"></div><h2 class="subhead">Влад</h2>${lifeHearts(h.hp,h.hpMax)}<div class="hero-skill-list"><h3>Умения</h3><div class="hero-skill-icons">${SKILLS.map(([id,n,cost])=>`<button class="hero-skill-icon ${game.ui.selectedSkill===id?'active':''} ${h.learnedSkills.includes(id)?'learned':''}" data-action="selectSkill" data-id="${id}" aria-pressed="${game.ui.selectedSkill===id}"><span>${skillArt(id)}</span><small>${n}</small></button>`).join('')}</div></div></aside><section class="panel section-panel hero-section"><nav class="tabs profile-tabs">${[['stats','Характеристики и умения'],['equipment','Снаряжение'],['bestiary','Бестиарий'],['chronicle','Летопись']].map(([id,n])=>`<button class="ghost ${t===id?'active':''}" data-action="heroTab" data-id="${id}">${n}</button>`).join('')}</nav><div class="profile-content">${detail}</div></section></div></div>`}
function production(){let out={wood:0,stone:0,grain:0,guard:0};for(let v of game.villagers){if(v.alive===false)continue;if(v.job==='wood')out.wood+=4;if(v.job==='stone')out.stone+=v.id==='erema'?4:3;if(v.job==='grain')out.grain+=5;if(v.job==='guard')out.guard+=4}return out}
const CLUES={marfa:[['Чужой голос','В топи услышишь знакомый голос — не спеши отвечать, милый. Сначала лицо разгляди. Туман чужими голосами говорить горазд.','Болото'],['Соль у порога','Соль у порога насыпь — шёпот ночью тише станет. А в топь соберёшься, возьми с собой. Не пожалей.','Болото']],erema:[['Знак на железе','На старой переправе железо осматривал — а на нём свежий знак. Круг замкнутый, будто кто вчера вырезал. На камнях у погоста такой же видали.','Погост'],['Старый гвоздь','Попробуй железом с переправы дверь укрепить. Думаю, удержит, если туман опять полезет. Обычной щеколде я бы не доверял.','Выселки']],prokop:[['Следы у опушки','Шёл по следу к бору, а он взял да оборвался. Посреди сухой земли, понимаешь? На опушку сходить бы. Только засветло.','Бор'],['Тропа без птиц','Где старая тропа к топи сворачивает, птицы вдруг молчат. Все до одной. Не по себе мне там, Влад.','Болото']],dunyasha:[['Имя за частоколом','Меня ночью звали… за частоколом. Голос брата, точь-в-точь его. Он ведь пропал. Я чуть не вышла, Влад. До сих пор руки дрожат.','Выселки'],['Огонёк у воды','За рекой огонёк был, один-единственный. К старой мельнице плыл. Против ветра! Я смотрела и боялась даже моргнуть.','Болото']],frol:[['Запись дозора','В старых записях дозора нашёл: холодные огни у погоста видели за ночь до густого тумана. Вот и думай теперь, совпадение ли.','Погост'],['Забытый дозорный','В конце дозорной книги имя сторожа пропущено. Только и написано: «не впускать после заката». Кого не впускать? Эх, знать бы.','Погост']],agafya:[['Почерневшая соль','После ночного стука соль у амбара вся чёрная стала. А огня рядом и не было! Ну скажи, как такое возможно?','Выселки'],['Зерно в кладовой','Кладовую ночью кто-то открыл. Зерно цело, ни горсточки не взяли. Только мокрые следы на полу — и дорожка к колодцу. Страшно мне, Влад.','Выселки']]};
function portrait(v){return v.id==='marfa'?'<img src="assets/marfa.png" alt="">':`<img src="assets/portrait-${['erema','prokop','dunyasha','frol','agafya'].includes(v.id)?v.id:'new'}.webp" alt="">`}
function talkToVillager(id){let v=game.villagers.find(x=>x.id===id);if(!v||v.alive===false)return;if(v.storyActive===false){notify(v.name+': не готов говорить или не знает ничего о прошлом деревни.');return}window.VillageProgress?.talk(game,id);if(typeof restoredHomeConversation==='function'&&restoredHomeConversation(id))return;let clues=CLUES[id]||[['Новый сосед',`${v.name} слышал у ворот тихий стук после заката. Следы вели к дороге, но обратно никто не шёл.`,'Выселки']];let seen=game.dialogueNotes.filter(n=>n.villagerId===id&&n.id.startsWith(id+'-')).length,index=Math.min(seen,clues.length-1),clue=clues[index],fresh=seen<clues.length;if(fresh){game.dialogueNotes.push({id:`${id}-${index}`,villagerId:id,speaker:v.name,title:clue[0],text:clue[1],place:clue[2],day:game.day});game.ui.diarySelection='note:'+id+'-'+index;game.journal.push(`${v.name}: ${clue[0]}. ${clue[1]}`)}modal('conversation',{villagerId:id,title:clue[0],text:clue[1],fresh})}
function villagersView(){let selected=game.villagers.find(v=>v.id===game.ui.selectedVillager)||game.villagers[0],idle=game.villagers.filter(v=>v.alive!==false&&!v.job).length,notes=game.dialogueNotes.filter(n=>n.villagerId===selected.id);return `<div class="screen-shell">${screenHead('Жители',`${game.villagers.filter(v=>v.alive!==false).length} живых · ${game.villagers.filter(v=>v.alive===false).length} погибших · ${idle} без дела`,false)}<div class="columns villagers-columns"><aside class="panel section-panel"><div class="list villager-list">${game.villagers.map(v=>`<button class="ghost villager-choice ${v.id===selected.id?'active':''}" data-action="selectVillager" data-id="${v.id}"><span class="villager-thumb">${portrait(v)}</span><span><strong>${esc(v.name)}</strong><small>${v.alive===false?'Погиб · ночь '+v.diedWave:esc(v.role)+' · '+JOBS[v.job||'none'][0]}</small></span><span class="note-count">${game.dialogueNotes.filter(n=>n.villagerId===v.id).length||''}</span></button>`).join('')}</div></aside><section class="panel section-panel villager-detail"><div class="villager-heading"><div class="villager-portrait">${portrait(selected)}</div><div><span class="eyebrow">${esc(selected.role)}</span><h2 class="subhead">${esc(selected.name)}</h2>${pendingResidentButton(selected.id)}<p class="serif">«${esc(selected.quote)}»</p><button class="button" data-action="talk" data-id="${selected.id}" ${selected.alive===false||selected.storyActive===false?'disabled':''}>${selected.alive===false?'Погиб в бою':selected.storyActive===false?'Не готов говорить':'Поговорить'}</button></div></div><div class="rule"></div><p class="muted small">${selected.alive===false?'Погиб в ночь '+selected.diedWave+'. Его работа и участие в дозоре прекращены.':selected.storyActive===false?'Фоновый житель: участвует в защите, но не открывает сюжетных записей.':'Сюжетный житель: его разговоры сохраняются в дневнике.'}</p>${selected.storyActive===false?'':`<h3 class="subhead">Открытые разговоры</h3><p class="muted small">Записки сохраняются в дневнике. Каждый новый разговор раскрывает ещё одну подробность.</p><div class="note-library">${notes.length?notes.map(n=>`<button class="note-slip" data-action="openNote" data-id="${n.id}"><span>День ${n.day} · ${esc(n.place)}</span><strong>${esc(n.title)}</strong><small>Открыть в дневнике</small></button>`).join(''):'<div class="empty">Пока нет записок. Начни разговор.</div>'}</div>`}<h3 class="subhead">Занятие</h3><div class="row" style="flex-wrap:wrap">${Object.entries(JOBS).map(([id,[name]])=>`<button class="ghost ${selected.job===id||(!selected.job&&id==='none')?'active':''}" data-action="job" data-id="${id}" ${selected.fixedRole||selected.alive===false?'disabled title="Занятие недоступно"':''}>${name}</button>`).join('')}</div>${selected.fixedRole?'<p class="muted small">Марфа хранит обряды. Её занятие не меняется.</p>':''}</section></div></div>`}
function bestiaryContent(){const oakDescription=oakBestiary();let filter=game.ui.beastFilter,items=CREATURES.filter(c=>filter==='Все'||c.area===filter||(filter==='Болото'&&c.id==='kikimora')),c=items.find(x=>x.id===game.ui.selectedBeast)||items[0],seen=game.bestiary[c.id]?.discovered&&!c.locked;return `<div class="profile-embedded"><div class="columns"><aside class="panel section-panel"><div class="tabs filter">${['Все','Лес','Болото','Деревня','Погост','Поле'].map(x=>`<button class="ghost ${filter===x?'active':''}" data-action="beastFilter" data-id="${x}">${x}</button>`).join('')}</div><div class="list">${items.map(x=>`<button class="ghost ${x.id===c.id?'active':''}" data-action="selectBeast" data-id="${x.id}">${icon(game.bestiary[x.id]?.discovered&&!x.locked?x.icon:44)} ${game.bestiary[x.id]?.discovered&&!x.locked?x.name:'???'} <span class="muted small">${x.area}</span></button>`).join('')||'<div class="empty">Нет записей</div>'}</div></aside><section class="panel section-panel"><div class="detail-image">${seen?(c.id==='ancient_oak'?'<img src="assets/oak-conversation.webp" alt="Дуб с цепями">':icon(c.icon)):brand(102,'large')}</div><div class="eyebrow">${seen?c.area:'Не исследовано'} · опасность ${seen?c.risk:'?'} / 5 · записей ${game.bestiary[c.id]?.notes||0}/3</div><h2 class="title">${seen?c.name:'???'}</h2><p class="muted">${seen?(c.id==='ancient_oak'?oakDescription:c.desc+' '+(window.BattleNarrative?.knowledge(game,c.id)||'')):'Исследуйте местность и переживайте ночные события, чтобы узнать об этом существе.'}</p>${seen?`<div class="stat-row"><strong>Повадки</strong><span>${c.habit}</span></div><div class="stat-row"><strong>Чего боится</strong><span>${c.weak}</span></div><div class="stat-row"><strong>Где встречается</strong><span>${c.area}</span></div>`:''}</section></div></div>`}

function bestiaryView(){game.ui.heroTab="bestiary";return heroView()}
function bindRuleCards(){
 const cards=[...document.querySelectorAll('.rule-card')];
 const align=()=>{cards.forEach(c=>c.querySelector('summary').style.minHeight='');if(window.innerWidth>700){const height=Math.max(...cards.map(c=>c.querySelector('summary').getBoundingClientRect().height));cards.forEach(c=>c.querySelector('summary').style.minHeight=height+'px')}};
 align();document.fonts?.ready.then(align);
 const observer=new ResizeObserver(()=>{if(cards[0]?.isConnected)align();else observer.disconnect()});if(cards[0])observer.observe(cards[0].parentElement);
 cards.forEach(card=>{let pinned=false,desired=false,animation=null;const summary=card.querySelector('summary'),content=card.querySelector('.rule-expanded');
 const reveal=open=>{if(desired===open)return;desired=open;const start=card.getBoundingClientRect().height;animation?.cancel();card.style.height='';card.open=true;const end=open?card.getBoundingClientRect().height:summary.getBoundingClientRect().height+2;summary.setAttribute('aria-expanded',String(open));content.inert=!open;card.classList.toggle('is-expanded',open);
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){card.open=open;return}
 card.style.height=start+'px';animation=card.animate([{height:start+'px'},{height:end+'px'}],{duration:480,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'});animation.onfinish=()=>{card.open=desired;card.style.height='';animation.cancel();animation=null};};
 summary.setAttribute('aria-expanded','false');content.inert=true;
 card.addEventListener('mouseenter',()=>{if(window.matchMedia('(hover: hover)').matches)reveal(true)});
 card.addEventListener('mouseleave',()=>{if(!pinned&&!card.contains(document.activeElement))reveal(false)});
 summary.addEventListener('click',e=>{e.preventDefault();pinned=!pinned;reveal(pinned)});
 card.addEventListener('keydown',e=>{if(e.key==='Escape'){pinned=false;reveal(false);summary.focus();e.stopPropagation()}});
 });
}
function warriorControlsView(){return `<section class="panel section-panel warrior-controls"><h3 class="subhead">Богатырь и управление</h3><p>Управляй Владом в деревне. Нажми на землю или объект, чтобы задать точку движения. Рядом с объектом появляются кнопки «Информация» и «Снос».</p><div class="shortcut-list">${[['Левая кнопка мыши · земля','Идти к выбранному месту'],['Двойной клик / Shift + клик','Бежать к месту'],['Левая кнопка мыши · объект','Идти к точке на объекте или рядом с ней']].map(([key,label])=>`<div class="setting-row"><strong>${label}</strong><span class="shortcut-key static">${key}</span></div>`).join('')}</div><p class="muted small">Во время диалогов, открытых окон и размещения построек движение приостанавливается.</p></section>`}
function rulesView(){const entering=game.ui.rulesReturn==='game';const sections=[
 [109,'Вечер','Задание → восстановление → знакомство → защита. Ночь начинается после выполнения обязательных задач. План подготовки показывает, что осталось.'],
 [110,'Ночь','Отрази нападение из леса. Щёлкни по врагу, чтобы подойти и атаковать. Пробел — удар, H — лечение.'],
 [106,'Влад','Береги жизни Влада. Опыт открывает уровни и умения; дневник хранит подсказки и сюжетные записи.'],
 [75,'Цель','Отрази три волны: по одной за ночь. В каждой следующей волне врагов больше. В третью ночь Леший сам вступит в бой.']];
 const guides=[['vyselki.png','Выселки: постройки и подготовка к ночи','Назначай жителям работу, чтобы получать материалы и зерно на рассвете. Для строительства выбери объект и свободный сухой участок; правая кнопка мыши подтверждает место. Материалы и еда принадлежат деревне, серебро — Владу. В окрестностях можно бесплатно заготавливать дерево и собирать камень. Домовой обменивает материалы на верёвку, краску и уголь, а за серебро продаёт лечение и постоянный оберег +1 к защите. Перед первой ночью восстанови церковь и торговое место, расчисти корни и поговори с Дубом. Перед второй — четыре вышки, дозорные, два дома и первые тотемы. Перед третьей — четыре стороны светлого периметра и расследование круга. Каждый тотем расходует один уголь перед ночью и отпугивает обычных врагов в радиусе 7 шагов раз в 6 секунд. Леший сильнее этого оберега. Дозорный стреляет раз в 8 секунд в радиусе 11; без назначенного жителя вышка не стреляет. Подготовка не расходуется повторно при повторе поражённой волны.'],['story-night-house.webp','Дом в ночи: неизвестность за дверью','Одна ночь — одна волна. Враги приходят с разных сторон и преследуют Влада, обходя препятствия. Во время нападения нижняя панель показывает снаряжение. После победы — короткая новелла и итоги: еда, работа жителей и защита деревни. В меню бой приостанавливается.'],['bogatyr.png','Влад — защитник Выселок','Сердца показывают оставшиеся жизни. В профиле распределяй очки характеристик, изучай умения и используй лечебные предметы. Открытые свидетельства жителей и результаты разведки сохраняются в дневнике.'],['scout-marsh.webp','Тропа за Выселками: поиск истока тумана','Отбей три ночных волны. После первой и второй будет короткий разговор с Тьмой, после третьей — с Лешим. Между волнами можно торговаться с Домовым в центре деревни. При поражении доступен повтор волны с запасами на её начало или загрузка сохранения.']];
 return `<div class="screen-shell rules-shell"><div class="rules-atmosphere" aria-hidden="true"><div class="rules-shade"></div>${Array.from({length:22},(_,i)=>`<i class="rules-firefly" style="--x:${(i*43+7)%100}%;--y:${(i*29+13)%100}%;--delay:-${i*.83}s;--duration:${9+i%6}s"></i>`).join('')}</div><header class="screen-head"><div><h1>Правила игры</h1></div><button class="ghost" data-action="rulesClose" aria-label="Закрыть правила">${brand(87)} Закрыть</button></header><div class="rules-intro"><h2>Вечером готовь Выселки. Ночью защищай деревню.</h2><p>Каждое решение оставляет след. Сведения жителей и разведка помогут выбрать путь, а ресурсы и защита дадут пережить ночь.</p></div><section class="panel section-panel warrior-rules"><h2 class="subhead">Богатырь и управление</h2><p>В первой деревне шесть жителей могут рассказать о прошлом, ещё семь не готовы говорить. Ночью все живые жители защищаются: по два противника на каждого, у Влада — до семи. В текущем шаблоне одна-две потери фоновых жителей обязательны. Два восстановленных дома и разговоры с тремя жителями снижают потери до одного; гибель сокращает рабочие руки и усиливает следующие волны. Влад свободно передвигается по деревне. Нажми на свободное место на земле — Влад пойдёт туда, обходя препятствия. Двойной клик или Shift вместе с кликом задаёт бег. Здания, деревья, камни и пруды нужно обходить.</p><p>Нажми на объект — Влад пойдёт к указанной точке на нём, если туда можно пройти, или остановится в ближайшем доступном месте. Рядом с объектом появляется светлый указатель: «Информация» открывает паспорт, «Снос» — предупреждение с подтверждением. При отходе указатель исчезает. Новый клик меняет маршрут.</p><p>При открытом окне и во время строительства Влад стоит на месте. Закрой окно или заверши размещение, чтобы продолжить движение. Его положение сохраняется вместе с игрой; камера следует за ним, когда он отходит от центра.</p></section><div class="rules-grid">${sections.map(([art,title,copy],i)=>`<details class="panel rule-card"><summary><span class="rule-number">0${i+1}</span><span class="rule-heading"><span class="rule-icon">${brand(art)}</span><h3>${title}</h3></span><p>${copy}</p><span class="rule-more">${brand(85)}<span>Подробнее</span></span></summary><div class="rule-expanded"><figure><img src="assets/${guides[i][0]}" alt="${guides[i][1]}" loading="lazy"><figcaption>${guides[i][1]}</figcaption></figure><p>${guides[i][2]}</p></div></details>`).join('')}</div><div class="rules-foot"><button class="button" data-action="rulesClose">${entering?'Понятно, в деревню':'Вернуться в меню'}</button></div></div>`}
function saveStoryMeta(s=game){if(s.ui.ritualMemoryActive)return {cover:window.RITUAL_MEMORY?.[s.ui.novelIndex]?.bg||'ritual-cult.png',stage:'Круг и чёрная земля'};if(s.ui.oakActive)return {cover:s.ui.oakMode==='first'?(window.OAK_FIRST_LINES?.[s.ui.novelIndex]?.bg||'oak-root-sign.webp'):'oak-conversation.webp',stage:s.ui.oakMode==='first'?'Горе пустило корни':'Разговор с дубом'};if(s.defense?.stage==='active')return {cover:'story-night-house.webp',stage:'Защита деревни · волна '+s.defense.wave+'/3'};if(s.defense?.stage==='dialogue')return {cover:WAVE_DIALOGUES[s.defense.wave]?.[s.ui.novelIndex]?.bg||'story-shadow.webp',stage:'После волны '+s.defense.wave};if(s.ui.waveTalk){const t=s.ui.waveTalk,e=(t.source==='oak'?window.WAVE_CONTENT.oak:window.WAVE_CONTENT.residents)[t.wave];return {cover:e?.lines?.[s.ui.novelIndex]?.bg||'oak-conversation.webp',stage:e?.title||'Разговор после ночи '+t.wave}}if(s.ui.memoryActive){const line=window.CHURCH_MEMORY?.[s.ui.novelIndex];return {cover:line?.bg||'memory-present-church.png',stage:'Воспоминание у церкви · '+((s.ui.novelIndex||0)+1)}}if(s.defense?.stage==='defeat')return {cover:'story-night-house.webp',stage:'Поражение · волна '+s.defense.wave};if(s.defense?.stage==='outcome')return {cover:'story-shadow.webp',stage:'Итоги ночи '+s.defense.wave};if(s.story?.lastStoryEvent)return {cover:s.story.lastStoryEvent.cover,stage:s.story.lastStoryEvent.stage};if(s.story?.oakFacts?.includes('forest-fear'))return {cover:'oak-conversation.webp',stage:'Кого боится лес · разговор записан'};if(s.story?.oakFirstCompleted)return {cover:'oak-buried-memory.webp',stage:'Горе пустило корни · разговор записан'};if(s.story?.oakRootKnown)return {cover:'oak-root-sign.webp',stage:'Знак на корне Дуба'};if(s.defense?.completed>=3)return {cover:'scout-forest.webp',stage:'Три ночи отражены'};const branch=s.story?.chapterDecision;if(branch==='guard')return {cover:'vyselki.png',stage:'Выселки укреплены'};if(branch==='search')return {cover:'scout-marsh.webp',stage:'Поиск истока тумана'};const explored=s.story?.explored||[];if(explored.includes('ruins'))return {cover:'scout-pogost.webp',stage:'Следы на погосте'};if(explored.includes('marsh'))return {cover:'scout-marsh.webp',stage:'Тропа через топь'};if(explored.includes('forest'))return {cover:'scout-forest.webp',stage:'Дозор в бору'};if(memoryKnown(s))return {cover:'memory-present-church.png',stage:'Прошлое Влада записано'};return {cover:'vyselki.png',stage:'Возвращение в Выселки'}}
function recordStoryEvent(type,cover,stage){game.story.lastStoryEvent={type,cover,stage,day:game.day}}
function announceStoryUnlocks(){if(game.screen!=='game'||game.phase!=='day'||game.ui.openModal||game.ui.oakEncounterActive||document.querySelector('.screen-curtain'))return;game.story.announcedTalks??=[];const available=[...readyWaveTopics('oak'),...readyWaveTopics('resident')];const fresh=available.filter(t=>!game.story.announcedTalks.includes(t.id));if(fresh.length){game.story.announcedTalks.push(...fresh.map(t=>t.id));notify(fresh.some(t=>t.id.startsWith('oak-'))?'У Дуба появился новый разговор. Задание добавлено.':'Жители хотят поговорить. Задание добавлено.','major')}}
function refreshActiveSave(){const index=game.ui.activeSaveSlot;if(!game.ui.sessionStarted||!Number.isInteger(index)||index<0||index>2||!game.saves[index])return;const slot=game.saves[index],copy=snapshot();game.saves[index]={...slot,day:game.day,...saveStoryMeta(),fear:game.fear,timestamp:Date.now(),savedAt:new Date().toLocaleString('ru-RU'),snapshot:copy}}
function discoverCreature(id,event){const entry=game.bestiary[id]??={discovered:false,notes:0};game.story.creatureEvidence??={};const evidence=game.story.creatureEvidence[id]??=[];if(evidence.includes(event))return false;evidence.push(event);const fresh=!entry.discovered;entry.discovered=true;entry.notes=Math.min(3,Math.max(entry.notes||0,evidence.length));if(fresh&&game.ui.sessionStarted)notify((CREATURES.find(c=>c.id===id)?.name||id)+' добавлен в бестиарий','action');return true}
function waveDiaryNotes(){const reports=game.story.waveReports||[];const legacy=Array.from({length:game.defense?.completed||0},(_,i)=>i+1).filter(w=>!reports.some(n=>n.wave===w)).map(w=>({id:'wave-report-'+w,wave:w,title:'Ночь '+w+' · деревня устояла',image:w===3?'scout-forest.webp':'story-shadow.webp',lead:(WAVE_DIALOGUES[w]||[]).map(l=>l.speaker+': '+l.text).join(' '),prototype:true}));return [...reports,...legacy].map(n=>({...n,hint:'Итоги ночи '+n.wave+(n.prototype?' · черновая сцена':''),place:'Выселки',aside:'Записано после завершения ночи.',question:'Проверить новые разговоры и подготовить деревню.'}))}
function saveCover(slot){return slot?.snapshot?saveStoryMeta(slot.snapshot).cover:slot?.cover||'vyselki.png'}
function savesView(){const canSave=game.ui.sessionStarted;return `<div class="screen-shell saves-shell"><header class="screen-head"><div><h1>Сохранения</h1></div><button class="ghost" data-action="savesClose">${brand(87)} Закрыть</button></header><div class="saves-intro"><p>Активная запись обновляется автоматически вместе с прогрессом. Остальные записи хранят свои состояния. Выбери запись для продолжения или сохранения.</p><span>${game.saves.filter(Boolean).length} / 3 занято</span></div><div class="saves-cards">${[0,1,2].map(i=>{const slot=game.saves[i],name=slot?.name||`Новая запись ${i+1}`;return `<article class="panel story-save ${slot?'':'empty'}"><div class="story-save-cover"><img src="assets/${saveCover(slot)}" alt="${slot?esc(slot.place):'Выселки'} — обложка истории"></div><div class="story-save-body"><label for="save-name-${i}">Название</label><input id="save-name-${i}" class="save-name" data-save-name="${i}" maxlength="48" value="${esc(name)}" aria-label="Название сохранения ${i+1}"><div class="story-save-meta">${slot?`<span>${game.ui.activeSaveSlot===i?'Автосохранение · ':''}${esc(slot.snapshot?saveStoryMeta(slot.snapshot).stage:slot.stage||'Возвращение в Выселки')} · день ${slot.day}</span><time datetime="${new Date(slot.timestamp||Date.now()).toISOString()}">${esc(slot.savedAt)}</time>`:'<span>Начни игру, чтобы сохранить её здесь</span>'}</div><div class="story-save-actions"><button class="button" data-action="loadSave" data-id="${i}" ${slot?'':'disabled'}>Продолжить</button><button class="ghost" data-action="writeSave" data-id="${i}" ${canSave?'':'disabled title="Сначала начни игру"'}>${slot?'Сохранить здесь':'Сохранить'}</button><button class="ghost delete" data-action="deleteSave" data-id="${i}" ${slot?'':'disabled'}>Удалить</button></div></div></article>`}).join('')}</div></div>`}
const DIARY_STORY=[
{id:'night',title:'Та ночь',hint:'Воспоминание Влада',place:'Родная деревня',image:'diary-sketch-village.svg',lead:'Мне было восемь. Люди стучали в дверь и требовали меня. Мать спрятала меня в погребе. Тень пришла позже — и те люди бежали от неё. Родителей утром уже не было.',aside:'Сначала пришли люди. Потом — Тень.',question:'Почему они искали именно меня?',unlock:()=>true},
{id:'church',title:'Заброшенная церковь',hint:'Пустые стены, но не пусто',place:'Погост',image:'diary-church.webp',lead:'За лесом стоит церковь с обрушенным куполом. Ограду давно поглотила трава, но у входа кто-то оставил свежий след. Стены молчат — слишком старательно.',aside:'Кто приходит сюда после заката?',question:'Проверить знак на камне.',unlock:()=>game.story.explored.includes('ruins')},
{id:'figures',title:'Кто они?',hint:'Люди — или уже нет',place:'Выселки',image:'diary-sketch-village.svg',lead:'Разные люди описывают одно и то же: знакомый голос за частоколом зовёт по имени. Никто не видел лица говорившего. Стоит ли отвечать тому, кто знает тебя?',aside:'Дуняша слышала голос брата.',question:'Сверить слова жителей.',unlock:()=>game.dialogueNotes.some(n=>n.id==='dunyasha-0')},
{id:'signs',title:'Знаки',hint:'Повторяются в разных местах',place:'Болото',image:'diary-sketch-marsh.svg',lead:'На железе переправы и на камнях у погоста — один замкнутый знак. На болоте туман будто повторяет его кругами на воде.',aside:'Одинаковый знак в двух местах.',question:'Кто оставляет отметки?',unlock:()=>game.story.explored.includes('marsh')&&game.dialogueNotes.some(n=>n.id==='erema-0')},
{id:'bell',title:'Сон о колоколе',hint:'Будто звал, но куда?',place:'Погост',image:'diary-church.webp',lead:'Ночью мне снился колокол. Он был расколот, но продолжал звонить без языка и без ветра. На рассвете холодный звук ещё стоял в ушах.',aside:'Запомнить направление звона.',question:'Не был ли это предупреждением?',unlock:()=>game.ui.nightCount>=2&&game.story.explored.includes('ruins')},
{id:'path',title:'Старый путь',hint:'Дорога через болота',place:'Бор',image:'diary-sketch-forest.svg',lead:'Тропа из бора выходит к переправе, а дальше уходит через топь к старой церкви. Птицы замолкают ещё до поворота к воде.',aside:'Дозор должен вернуться до темноты.',question:'На карте есть второй путь?',unlock:()=>game.story.explored.includes('forest')},
{id:'unknown',title:'Неизвестное',hint:'Пока слишком мало…',place:'Выселки',image:'diary-sketch-village.svg',lead:'С каждой найденной нитью становится яснее: туман не пришёл случайно. Он ждал возвращения кого-то одного.',aside:'Исток тумана впереди.',question:'Что скрывает прошлая ночь?',unlock:()=>!!game.story.chapterDecision}
];
function diaryPages(){return [...DIARY_STORY.filter(e=>e.unlock()),...memoryNotes(),...oakNotes(),...waveDiaryNotes(),...(window.ritualDiaryNotes?.()||[]),...game.dialogueNotes.filter(n=>n.id!=='oak-first'&&(n.id!=='oak-wave-2'||!game.story.oakFacts?.length)).map(n=>({id:'note:'+n.id,title:n.title,hint:n.speaker+' · день '+n.day,place:n.place,image:'diary-sketch-'+({Болото:'marsh',Бор:'forest',Погост:'ruins',Выселки:'village'}[n.place]||'village')+'.svg',lead:n.text,aside:'Со слов: '+n.speaker,question:'Проверить это свидетельство.',note:true}))]}
function diaryView(){const pages=diaryPages(),selected=game.ui.diarySelection||'night',index=Math.max(0,pages.findIndex(e=>e.id===selected)),n=pages[index];game.ui.diarySelection=n.id;const known=game.dialogueNotes,found=STORY_FINDS.map(f=>({...f,on:game.hero.bag.some(b=>b.itemId===f.name)}));return `<div class="screen-shell diary-shell">${screenHead('Дневник','',false)}<div class="diary-layout"><aside class="diary-contents"><div class="diary-contents-title">ЗАПИСИ ВЛАДА</div><nav aria-label="Страницы дневника">${[...DIARY_STORY,...memoryNotes(),...oakNotes(),...waveDiaryNotes(),...(window.ritualDiaryNotes?.()||[])].map((e,i)=>{let open=e.unlock?e.unlock():true;return `<button class="diary-chapter ${selected===e.id?'active':''}" data-action="diarySelect" data-id="${e.id}" ${open?'':'disabled'}><span class="diary-chapter-mark">${brand(open?([97,96,95,103,91,90,102][i]||103):102)}</span><span><strong>${open?e.title:'Неизвестное'}</strong><small>${open?e.hint:'Пока слишком мало…'}</small></span></button>`}).join('')}</nav><div class="diary-conversations"><h3>Разговоры</h3>${known.length?known.map(note=>`<button class="diary-chapter diary-talk ${selected==='note:'+note.id?'active':''}" data-action="diarySelect" data-id="note:${note.id}"><span class="diary-chapter-mark">${brand(88)}</span><span><strong>${esc(note.title)}</strong><small>${esc(note.speaker)} · день ${note.day}</small></span></button>`).join(''):'<p>Поговори с жителями, чтобы сохранить их свидетельства.</p>'}</div></aside><div class="diary-main"><div class="diary-book" key="${n.id}"><div class="diary-spine"></div><section class="diary-leaf diary-left"><span class="diary-corner-ornament" aria-hidden="true">☨</span><h2>${esc(n.title)}</h2><div class="diary-red-stroke"></div><p class="diary-hand diary-lead">${esc(n.lead)}</p><div class="diary-scribble"><span>${esc(n.aside)}</span><em>${esc(n.question)}</em></div><figure class="diary-picture"><img src="assets/${n.image}" alt="Зарисовка: ${esc(n.place)}"><figcaption>${esc(n.place)}${n.note?' · со слов '+esc(known.find(x=>'note:'+x.id===n.id)?.speaker):''}</figcaption></figure></section><section class="diary-leaf diary-right">${window.ProgressLinks?progressLinksView():''}<h2>Находки</h2><div class="diary-finds">${found.map(item=>`<div class="diary-find ${item.on?'':'undiscovered'}"><div class="diary-find-frame">${item.on?`<img src="assets/diary-item-${item.asset}.webp" alt="${item.name}">`:'<span>?</span>'}</div><strong>${item.on?item.name:'Не найдено'}</strong><small>${item.on?item.where:'Ещё впереди'}</small></div>`).join('')}</div>${memoryKnown()?`<h2>Из воспоминания</h2><div class="diary-scribble"><span>Металлический знак и промокшее письмо</span><em>Символ с деревянной птицы. В письме — «мальчик», «жив», «Феофан» и родная деревня.</em></div>`:''}<h2 class="diary-map-title">Путь</h2><button class="diary-map" data-action="map" aria-label="Открыть карту и нити судьбы"><img src="assets/diary-route.webp" alt="Рисованная карта пути от деревни через болота к погосту"><span class="diary-map-label village">Выселки</span><span class="diary-map-label marsh">Болото</span><span class="diary-map-label ruins">Погост</span><span class="diary-map-hint">Открыть карту</span></button><div class="diary-map-legend"><span>◉ Текущее место</span><span>· · · Пройденный путь</span></div></section></div><div class="diary-controls"><button class="ghost" data-action="diaryPage" data-id="-1" ${index===0?'disabled':''}>${brand(83)} Ранее</button><span>${index+1} / ${pages.length}</span><button class="ghost" data-action="diaryPage" data-id="1" ${index===pages.length-1?'disabled':''}>Далее ${brand(84)}</button></div></div></div></div>`}

function settingsView(){const d=game.ui.settingsDraft||structuredClone(game.settings),tab=game.ui.settingsTab;let content='';const slider=(id,label)=>`<div class="setting-row"><strong>${label}</strong><div class="row"><input type="range" min="0" max="100" value="${d[id]}" data-setting="${id}"><span class="small">${d[id]}</span></div></div>`;const choice=(id,label,vals)=>`<div class="setting-row"><strong>${label}</strong><select data-setting="${id}">${vals.map(v=>`<option value="${v}" ${d[id]===v?'selected':''}>${v}</option>`).join('')}</select></div>`;const check=(id,label)=>`<div class="setting-row"><strong>${label}</strong><input type="checkbox" data-setting="${id}" ${d[id]?'checked':''}></div>`;if(tab==='sound')content='<p class="muted small">Музыка меняется вместе со сценой. Звук включается после первого нажатия.</p>'+check('muted','Выключить весь звук')+[['master','Общая громкость'],['music','Громкость музыки'],['effects','Громкость звуков']].map(([id,n])=>slider(id,n)).join('');if(tab==='image')content=check('fullscreen','Полный экран')+choice('quality','Качество света и отражений',['Автоматически','Общий вид','Деревня','Рядом','Крупно'])+choice('fog','Туман',['Лёгкий','Густой','Непроглядный'])+check('grain','Зерно плёнки')+slider('brightness','Яркость');if(tab==='game')content=choice('difficulty','Сложность',['Лучина','Сказ','Былина'])+`<div class="setting-row"><strong>Скорость текста</strong><div class="row"><input type="range" min="1" max="5" value="${d.textSpeed}" data-setting="textSpeed"><span>${d.textSpeed}/5</span></div></div>`+check('hints','Подсказки действий');if(tab==='controls')content=warriorControlsView()+`<h3 class="subhead shortcut-heading">Быстрый доступ к разделам</h3><p class="muted small">Нажми на клавишу, чтобы переназначить её. Сочетания действуют в игровом экране.</p><div class="shortcut-list">${Object.entries({journal:'Дневник',map:'Карта и нити судьбы',hero:'Профиль богатыря',villagers:'Жители',bestiary:'Бестиарий',scout:'Разведка',settings:'Настройки',sound:'Звук',saves:'Сохранения',tray:'Постройки и рынок',night:'Завершить день',quickSave:'Быстрое сохранение'}).map(([id,n])=>`<div class="setting-row"><strong>${n}</strong><button class="ghost shortcut-key" data-action="remap" data-id="${id}">${game.ui.remap===id?'Нажми клавишу…':d.keys[id]===' '?'Пробел':esc(d.keys[id])}</button></div>`).join('')}</div><h3 class="subhead shortcut-heading">В сценах и разделах</h3><div class="shortcut-list">${[['Пробел в бою','Ударить ближайшего врага'],['H / Р в бою','Использовать лечебный корень'],['F / А в бою','Зажечь фонарь: задержать врагов рядом за 1 свечу'],['Щелчок по врагу','Подойти и атаковать'],['Tab / Enter','Выбрать и нажать кнопку'],['Esc','Закрыть окно / вернуться назад'],['Enter / Пробел','Продолжить диалог'],['1–3','Выбрать ответ в диалоге'],['1–6','Выбрать постройку или товар'],['R / К','Повернуть выбранную постройку'],['Enter / Esc','Установить постройку / отменить размещение'],['Колесо мыши / + / −','Изменить масштаб деревни'],['Зажать колесо мыши','Перемещаться по карте'],['Правая кнопка мыши','Установить выбранную постройку'],['Левая кнопка мыши','Идти к месту / подойти к объекту'],['← / →','Листать дневник'],['1–4','Выбрать место на карте или вкладку профиля']].map(([key,label])=>`<div class="setting-row"><strong>${label}</strong><span class="shortcut-key static">${key}</span></div>`).join('')}</div>`;return `<div class="screen-shell settings-shell">${screenHead('Настройки','')}<div class="columns"><aside class="panel section-panel"><nav class="list">${[['sound','Звук'],['image','Изображение'],['game','Игра'],['controls','Управление']].map(([id,n])=>`<button class="ghost ${tab===id?'active':''}" data-action="settingsTab" data-id="${id}">${n}</button>`).join('')}</nav></aside><section class="panel section-panel"><h2 class="subhead">${{sound:'Звук',image:'Изображение',game:'Игра',controls:'Управление'}[tab]}</h2>${content}<div class="between" style="margin-top:25px;flex-wrap:wrap"><span class="small muted">${game.ui.settingsDirty?'Есть несохранённые изменения':'Все изменения сохранены'}</span><div class="row"><button class="ghost" data-action="settingsDefault">По умолчанию</button><button class="button" data-action="settingsApply" ${game.ui.settingsDirty?'':'disabled'}>Применить</button></div></div></section></div></div>`}
function exitView(){return `${bg('forest.png')}<div class="death-content"><span class="eyebrow">Путь прерван</span><h1>Выселки будут ждать</h1><p class="serif text-summary">Туман никуда не исчез. Вернись, когда будешь готов.</p><div class="row"><button class="button" data-action="menu">Вернуться в меню</button></div></div>`}
function deathView(){return `${bg('swamp.png')}<div class="death-content"><span class="eyebrow">Конец пути · День ${game.day}</span><h1>Туман забрал тебя</h1><p class="serif text-summary">Выселки запомнят того, кто остался до рассвета.</p><p class="muted">Ночей пережито: ${game.ui.nightCount} · Изб: ${game.buildings.hut} · Душ уцелело: ${game.villagers.filter(v=>v.alive!==false).length} · Нечисти изучено: ${CREATURES.filter(c=>game.bestiary[c.id]?.discovered).length}</p><div class="row"><button class="button" data-action="saves">Загрузить запись</button><button class="ghost" data-action="new">Начать заново</button><button class="ghost" data-action="menu">В меню</button></div></div>`}
const NATURE_YIELD={broken_fence:{wood:5},tent_ruin:{wood:4,cloth:1},roots:{wood:2},tree:{wood:8},rock:{stone:6},birch_grove:{wood:16},spruce_grove:{wood:18},fallen_tree:{wood:6},stump:{wood:3},stump_broken:{wood:2},stump_mushroom:{wood:2},bush_green:{wood:1},bush_dry:{wood:2}};
function natureYield(object){return object&&!object.built?NATURE_YIELD[object.id]||null:null}
function yieldLabel(reward){return Object.entries(reward).map(([id,n])=>`${RES[id][0]} +${n}`).join(', ')}
function objectPassportView(object,build,def){const natural=!!natureYield(object),residents=object.residents||[];const contact={ancient_oak:'Реагирует на движение рядом. Можно поговорить с дубом и выбрать тему.',circle:'Можно пройти в центр круга. Руны пробуждаются при приближении.',bridge:'Можно пройти по мосту на другой берег.',hut:'Жители доступны в разделе «Жители»: там можно поговорить с ними.',chapel:'Можно подойти к развалинам и наблюдать рунные явления.',well:'Обеспечивает деревню водой.',tower:'Помогает следить за лесными тропами.',lantern:'Освещает ближайшую тропу.'};return `<dl class="object-passport"><div><dt>Тип</dt><dd>${natural?'Природный объект':object.id==='hut'?'Жилой дом':build?'Постройка':'Объект окружения'}</dd></div><div><dt>Функции</dt><dd>${esc((object.built?build?.desc:null)||contact[object.id]||'Часть деревенского окружения. Дополнительных игровых действий пока нет.')}</dd></div><div><dt>Взаимодействие</dt><dd>${esc(contact[object.id]||(natural?'Можно расчистить и получить ресурсы.':'Можно осмотреть или снести с подтверждением.'))}</dd></div>${object.id==='hut'?`<div><dt>Жители</dt><dd>${residents.length?residents.map(v=>`<button class="ghost" data-action="talk" data-id="${esc(v.id)}">${esc(v.name)}</button>`).join(' '):'В этом доме пока никто не размещён.'}</dd></div>`:''}${object.id==='chapel'&&memoryKnown()?`<div><dt>Воспоминание Влада</dt><dd>Разрушенная обрядами церковь в деревне родителей напомнила о другом доме, где Феофан растил Влада. Подробности записаны в дневнике.</dd></div>`:''}${def?.footprint?`<div><dt>Размер</dt><dd>${def.footprint.join(' × ')} клеток</dd></div>`:''}</dl>`}
function modalView(){const progressModal=typeof villageProgressModal==='function'?villageProgressModal(game.ui.openModal):'';if(progressModal)return progressModal;let m=game.ui.openModal,close=`<button class="ghost" data-action="closeModal" aria-label="Закрыть">${brand(87)}</button>`,body='',title='';const defense=defenseModal(m);if(defense){title=defense.title;body=defense.body;if(m.type==='defenseDefeat')close=''}if(m.type==='villageObject'){const object=m.object,build=BUILD.find(b=>b.id===object.id),def=[...(window.LPK_MODELS||[]),...(window.LPK_ASSETS||[])].find(d=>d.id===object.id);title=object.name||build?.name||def?.name||({lantern:'Фонарь',woodpile:'Поленница',tree:'Дерево',rock:'Камень'})[object.id]||'Объект деревни';const descriptions={market_ruin:'Пустые торговые прилавки старой деревни. Домовой торгует поблизости.',tent_ruin:'Покосившаяся палатка с потёртой тканью. След прежнего торгового двора.',house_ruin:'Разрушенная изба. Здесь никто не живёт.',gate_ruin:'Остатки старого въезда. Возле ворот оставлен свободный проход.',broken_fence:'Уцелевший участок деревянного частокола.',totem:'Деревянный обрядовый столб с резными лицами и красными обвязками.',domovoy:'Домовой помогает пополнить запасы: лечебные корни, зерно, соль, свечи и усиление оберегов. Подойди к нему и выбери «Торговать».',ancient_oak:'Старый дуб с цепями у лесной кромки. Его ветви откликаются на шаги, а сам он готов поговорить.',barrel_open:'Открытая бочка для хозяйственных запасов.',roots:'Высохшие корни у лесной кромки.',ritual_stump:'На старом пне оставлен красный знак.',skull_human:'Старый череп среди следов обряда.',lantern:'Деревянный фонарь освещает тропу и ближайший двор.',woodpile:'Запас сухих брёвен для печей и строительства.',barrel:'Бочка для деревенских припасов.',barrels_stack:'Бочки во дворе: запас еды и воды.',crate:'Деревянный ящик для хозяйственных запасов.',yard_table:'Общий стол во дворе. Здесь жители встречаются и обмениваются новостями.',stump:'Пень на месте срубленного дерева.',stump_mushroom:'Старый пень, заросший мхом и грибами.',fallen_tree:'Поваленное дерево среди лесных троп.',bush_green:'Лесной кустарник на опушке.',oven:'Печь согревает деревню и помогает жителям пережить ночь.',circle:'След культистского обряда у леса. Знакомые знаки пробуждают память Влада.',totem:'Костяной оберег против лесной нечисти.',tower:'Вышка для наблюдения за дорогой и лесной кромкой.',hut:'Жилой дом из бревна. Во дворе хранят припасы и дрова.',chapel:'Старая часовня: крест стоит над камнями, которые помнят прежние обычаи.',well:'Деревенский колодец. В тёмное время сюда ходят с фонарём.',bone_totem:'Оберег на границе поселения.',watchtower:'Дозорная вышка у лесных троп.'};body=`<p>${esc(descriptions[object.id]||'Объект поселения или лесного окружения.')}</p>${object.built&&build?`<p>Эффект: ${esc(build.desc)}</p>`:''}${objectPassportView(object,build,def)}${typeof restorationObjectView==='function'?restorationObjectView(object):''}${object.id==='chapel'&&game.story.churchMemoryAvailable&&!game.story.churchMemoryCompleted?`<button class="button church-memory-action" data-action="churchMemory">${brand(103)} Вспомнить прошлое</button>`:''}<p class="small muted">${object.built?'Построено игроком. Снос отключит эффект постройки.':'Часть окружения деревни.'}</p><div class="row"><button class="ghost" data-action="closeModal">Закрыть</button>${object.id==='ancient_oak'?`<button class="button church-memory-action" data-action="oakTalk">${brand(82)} Поговорить</button>`:`<button class="button ${object.id==='circle'&&game.story.ritualMemoryCompleted?'ritual-demolish':''}" data-action="demolishAsk">${natureYield(object)?'Расчистить':'Снести'}</button>`}</div>`}if(m.type==='journal'){title='Дневник';body=`<div class="columns"><div><h3 class="subhead">${game.quests[0].title}</h3><p>${game.quests[0].desc} · ${game.quests[0].progress}/${game.quests[0].goal}</p><h3 class="subhead">Другие задачи</h3>${game.quests.slice(1).map(q=>`<p style="${q.done?'text-decoration:line-through;opacity:.6':''}">${q.title} · ${q.progress}/${q.goal}</p>`).join('')}</div><div><span class="eyebrow">Записи</span><div class="ledger">${game.journal.map(x=>`<p>${esc(x)}</p>`).join('')}</div><button class="ghost" data-action="threads">Нити судьбы</button></div></div>`}if(m.type==='map'){title='Карта окрестностей';body=`<div class="map-panel"><span class="map-pin current" style="left:28%;top:66%">◈ Выселки · вы здесь</span><span class="map-pin" style="left:48%;top:38%">Бор</span><span class="map-pin" style="left:68%;top:69%">Болото</span><span class="map-pin" style="left:79%;top:26%">Погост</span></div><p>Задача: ${game.quests[0].title}. Неразведанные тропы скрыты туманом.</p><button class="button" data-action="scout">Перейти к разведке</button>`}if(m.type==='conversation'){let v=game.villagers.find(x=>x.id===m.villagerId);title=m.fresh?'Новая записка':'Разговор';body=`<div class="conversation-content"><div class="villager-thumb">${portrait(v)}</div><div><span class="eyebrow conversation-speaker">${speakerMark(v.name,['marfa','dunyasha','agafya'].includes(v.id)?'woman':'man')}<span>${esc(v.name)} · день ${game.day}</span></span><h3 class="subhead">${esc(m.title)}</h3><p class="serif">«${esc(m.text)}»</p><button class="button" data-action="journal">${m.fresh?'Открыть новую запись':'Открыть дневник'}</button></div></div>`}if(m.type==='quick'){title='Быстрые настройки';body=`<div class="setting-row"><strong>Громкость музыки</strong><input type="range" min="0" max="100" value="${game.settings.music}" data-quick="music"></div><div class="setting-row"><strong>Громкость звуков</strong><input type="range" min="0" max="100" value="${game.settings.effects}" data-quick="effects"></div><div class="row window-actions"><button class="button" data-action="settings">Все настройки</button><button class="ghost" data-action="quickSave">Сохранить</button><button class="ghost" data-action="menu">В меню</button></div>`}if(m.type==='night'){let ev=EVENTS[(game.day-1)%EVENTS.length];title=`Ночь · День ${game.day}`;body=`<span class="eyebrow">Ночное событие</span><h3 class="subhead">${ev.title}</h3><p>${ev.text}</p>${ev.options.map((o,i)=>`<button class="option" data-action="nightChoice" data-id="${i}" ${o.need&&!canAfford(o.need)?`disabled title="${missing(o.need)}"`:''}><span>${o.label}</span><small>${o.need&&!canAfford(o.need)?missing(o.need):o.hint}</small></button>`).join('')}`;close=''}if(m.type==='outcome'){title=game.defense.stage==='outcome'?'Ночь отбита · итоги':'Рассвет · итоги ночи';body=`<div class="event-result"><h3 class="subhead">${m.title}</h3><p>${m.text}</p><ul>${m.lines.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><button class="button" data-action="dawn">${game.defense.stage==='outcome'?'Вернуться в деревню':'Встретить рассвет'}</button>`;close=''}if(m.type==='scoutResult'){title=m.title;body=`<p>Дозор вернулся до сумерек.</p><ul class="result-list">${m.lines.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="button" data-action="closeModal">Вернуться</button>`}if(m.type==='novelJournal'){title='Журнал реплик';body=`<div class="ledger">${game.ui.novelHistory.map(h=>`<p><strong>${esc(h.speaker)}:</strong> ${esc(h.text)}</p>`).join('')}</div>`}if(m.type==='confirm'){title=m.title;body=`<p>${m.text}</p><div class="row"><button class="ghost" data-action="closeModal">${m.cancel||'Остаться'}</button><button class="button" data-action="confirm">${m.confirm||'Продолжить'}</button></div>`}if(m.type==='death'){title='Туман сомкнулся';body=`<p>Защитник не дожил до рассвета.</p><button class="button" data-action="deathScreen">Итоги прохождения</button>`;close=''}return `<div class="modal-layer" role="presentation"><div class="modal modal-${m.type} ${m.type==='conversation'?'voice-'+m.villagerId:''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><div><h2>${title}</h2></div>${close}</header>${body}</div></div>`}
function newGame(){modal('confirm',{title:hasSave()?'Начать заново?':'Начать историю?',text:hasSave()?'Новая игра начнётся с пролога. Три сохранённые истории останутся доступными.':'История начнётся с пролога. Готов отправиться в путь?',confirm:'Начать',onConfirm:'new'})}
function beginNewConfirmed(){let old=game.saves,settings=game.settings;game=initial();game.saves=old;game.ui.savesMigrated=true;game.settings=settings;go('prologue')}
function build(id,position){if(!position)return;let b=BUILD.find(x=>x.id===id);if(!b)return;if(!canAfford(b.cost)){notify(missing(b.cost),'error');return}for(let [k,v] of Object.entries(b.cost))game.resources[k]-=v;game.buildings[id]++;game.villageLayout??=[];game.villageLayout.push(position);game.ui.placing=null;window.village3D?.cancel();if(id==='hut'){let n=game.villagers.length;for(let i=0;i<2;i++)game.villagers.push({id:'new'+(n+i),name:['Мирон','Лада','Савва','Ульяна'][(n+i)%4],role:'житель',home:{x:position.x,z:position.z},job:null,fear:game.fear,quote:'Здесь можно начать заново.',fixedRole:false,storyActive:false,alive:true})}gainXp(10);game.journal.push(`Построено: ${b.name}.`);render();for(let [k,v] of Object.entries(b.cost))pulseResource(k,-v);notify(`${b.name} построена`,'action')}
function buy(id){let m=MARKET.find(x=>x.id===id);if(!m)return;if(game.resources.silver<m.price){notify('Не хватает серебра','error');return}game.resources.silver-=m.price;game.resources[id]+=m.qty;render();pulseResource(id,m.qty);pulseResource('silver',-m.price)}
function startNight(){if(game.phase!=='day'||game.defense.completed>=3)return;if(window.VillageProgress&&!VillageProgress.readiness(game).ready){modal('restoration');return}beginDefense()}
function chooseNight(index){
 if(game.phase!=='event')return;
 let ev=EVENTS[(game.day-1)%EVENTS.length],choice=ev.options[index],levelBefore=game.hero.level;if(!choice)return;
 if(choice.need&&!canAfford(choice.need)){notify(missing(choice.need),'error');return}
 const learned=game.hero.learnedSkills,stats=game.hero.stats,buildings=game.buildings,difficulty=game.settings.difficulty;
 let lines=[],rawDamage=0;
 for(let [k,v] of Object.entries(choice.effect)){
  if(k==='hp'){rawDamage=v;let blocked=v<0&&learned.includes('wall')?Math.min(-v,1):0;let actual=v+blocked;game.hero.hp=Math.max(0,Math.min(game.hero.hpMax,game.hero.hp+actual));lines.push(`Жизни ${actual}`);if(blocked)lines.push('Стена щитом: потеря жизни предотвращена')}
  else if(k==='xp'){let bonus=rawDamage<0&&learned.includes('strike')?5+2*Math.max(0,stats.str-3):0;gainXp(v+bonus,true);lines.push(`Опыт +${v+bonus}`);if(bonus)lines.push(`Удар богатыря и сила: опыт +${bonus}`)}
  else if(k==='fear'){game.fear=Math.max(0,Math.min(100,game.fear+v));lines.push(`Страх ${v>0?'+':''}${v}`)}
  else{game.resources[k]=Math.max(0,game.resources[k]+v);lines.push(`${RES[k][0]} ${v>0?'+':''}${v}`)}
 }
 // Some bold choices grant experience without an explicit XP effect.
 if(rawDamage<0&&!('xp' in choice.effect)&&learned.includes('strike')){let bonus=5+2*Math.max(0,stats.str-3);gainXp(bonus,true);lines.push(`Удар богатыря: опыт +${bonus}`)}
 let food=Math.max(1,4+2*buildings.hut-2*buildings.oven-(learned.includes('bless')?4:0));
 if(game.resources.grain<food){lines.push(`Зерна не хватило: −${game.resources.grain}, страх +10`);game.resources.grain=0;game.fear=Math.min(100,game.fear+10)}
 else{game.resources.grain-=food;lines.push(`Зерно −${food} · еда для жителей`)}
 let silver=10+2*Math.max(0,stats.luck-2);game.resources.silver+=silver;lines.push(`Серебро +${silver}`);
 let p=production();for(let k of ['wood','stone','grain'])if(p[k]){game.resources[k]+=p[k];lines.push(`${RES[k][0]} +${p[k]} · работа жителей`)}
 let shield=5*buildings.tower+3*buildings.totem+2*buildings.well+p.guard+(learned.includes('ward')?4+2*Math.max(0,stats.faith-2):0)+(learned.includes('cry')?5:0);
 if(buildings.circle&&game.resources.candles>0){let rites=Math.min(buildings.circle,game.resources.candles);game.resources.candles-=rites;shield+=4*rites;lines.push(`Ритуальный круг: свечи −${rites}, страх −${4*rites}`)}
 game.fear=Math.max(0,game.fear-shield);if(shield)lines.push(`Защита: страх −${shield}`);
 if(buildings.oven&&game.hero.hp>0&&game.hero.hp<game.hero.hpMax){game.hero.hp=Math.min(game.hero.hpMax,game.hero.hp+1);lines.push('Тепло печи: жизни +1')}
 let difficultyFear=({'Лучина':-4,'Сказ':0,'Былина':7})[difficulty]||0;
 if(difficultyFear){game.fear=Math.max(0,Math.min(100,game.fear+difficultyFear));lines.push(`Сложность «${difficulty}»: страх ${difficultyFear>0?'+':''}${difficultyFear}`)}
 if(game.hero.level>levelBefore)lines.push(`Новый уровень · ${game.hero.level}`);
 game.ui.nightCount++;game.phase='outcome';game.journal.push(`Ночь ${game.day}: ${ev.title}. ${choice.result}`);
 let creature=['kikimora','domovoy','bolotnik'][((game.day-1)%3)];game.bestiary[creature].discovered=true;game.bestiary[creature].notes=Math.min(3,game.bestiary[creature].notes+1);
 game.ui.outcome={title:ev.title,text:choice.result,lines};modal('outcome',game.ui.outcome)
}
function dawn(){if(defenseReturn())return;if(game.phase!=='outcome')return;if(game.hero.hp<=0){modal('death');return}game.day++;game.phase='day';game.ui.openModal=null;game.ui.outcome=null;autoSave();if(game.ui.nightCount>=3&&!game.story.chapterDecision){go('chapter');return}if(game.screen==='game')commitGo('game');else go('game');notify(`Наступил день ${game.day}`)}
function snapshot(){let copy=structuredClone(game);copy.saves=[];copy.screen=game.ui.ritualMemoryActive||game.ui.memoryActive||game.ui.oakActive||game.ui.waveTalk||defenseNovelActive()?'novel':'game';copy.ui.openModal=null;copy.ui.settingsDraft=null;copy.ui.placing=null;return copy}
function writeSave(index,nameOverride){if(!game.ui.sessionStarted||index<0||index>2)return;let old=game.saves[index],input=app.querySelector(`[data-save-name="${index}"]`),name=(nameOverride||input?.value||old?.name||`Выселки · День ${game.day}`).trim().slice(0,48)||`Выселки · День ${game.day}`;game.ui.activeSaveSlot=index;game.saves[index]={slotId:index,name,day:game.day,place:'Выселки',...saveStoryMeta(),fear:game.fear,savedAt:new Date().toLocaleString('ru-RU'),timestamp:Date.now(),snapshot:snapshot()};notify('Игра сохранена','action');saveLocal();render()}
function autoSave(){saveLocal()}
function loadSave(index){let slot=game.saves[index];if(!slot)return;let saves=game.saves,settings=game.settings;game=hydrateState(structuredClone(slot.snapshot));game.dialogueNotes??=[];game.ui.diaryPage??=0;game.ui.mapSelection??='village';game.saves=saves;game.settings=settings;game.ui.openModal=null;game.ui.sessionStarted=true;game.ui.selectedSave=index;game.ui.activeSaveSlot=index;game.ui.bottomPanelOpen=false;const target=game.ui.ritualMemoryActive||game.ui.memoryActive||game.ui.oakActive||game.ui.waveTalk||defenseNovelActive()?'novel':'game';if(game.screen===target)commitGo(target);else go(target);notify(`Загружено: день ${game.day}`)}
function confirmAction(m){let code=m.onConfirm,id=m.id;game.ui.openModal=null;if(code==='demolishObject'){const object=m.object;const protectedReason=typeof restorationDemolitionReason==='function'?restorationDemolitionReason(object):null;if(protectedReason){notify(protectedReason,'error');render();return;}if(!object||(!object.built&&(game.sceneRemoved||[]).includes(object.key)))return;const reward=natureYield(object);if(object.built){const index=(game.villageLayout||[]).findIndex(p=>p.id===object.id&&p.x===object.x&&p.z===object.z);if(index>=0){game.villageLayout.splice(index,1);game.buildings[object.id]=Math.max(0,(game.buildings[object.id]||0)-1)}}else{game.sceneRemoved??=[];if(!game.sceneRemoved.includes(object.key))game.sceneRemoved.push(object.key)}if(reward){for(const [resource,amount] of Object.entries(reward))game.resources[resource]+=amount;if(Number.isFinite(object.x)&&Number.isFinite(object.z)){game.villageClearings??=[];if(!game.villageClearings.some(p=>p.key===object.key))game.villageClearings.push({key:object.key,x:object.x,z:object.z,radius:8})}}window.VillageProgress?.clear(game,object);game.journal.push(reward?'Расчищен природный объект: '+yieldLabel(reward)+'. Освобождённый участок открыт для строительства.':'Снесён объект деревни без возврата ресурсов.');render();notify(reward?'Получено: '+yieldLabel(reward):'Объект снесён');}else if(code==='new')beginNewConfirmed();else if(code==='delete'){game.saves[id]=null;if(game.ui.activeSaveSlot===Number(id))game.ui.activeSaveSlot=null;render();notify('Запись стёрта')}else if(code==='overwrite'){writeSave(id,m.name)}else if(code==='exit'){go('exit')}else if(code==='default'){game.ui.settingsDraft=baseSettings();game.ui.settingsDirty=true;render()}}
function handleAction(action,id,el){if(action==='oakEncounterNext'){nextOakEncounter();return}if(action==='oakEncounterLater'){endOakEncounter();return}if(game.ui.oakEncounterActive&&!['menu','settings','saves','continue','quick','sound','closeModal'].includes(action))return;if(typeof handleVillageProgressAction==='function'&&handleVillageProgressAction(action,id))return;if(handleDefenseAction(action,id))return;if(action==='oakWaveTalk'||action==='residentWaveTalk'){beginWaveConversation(action==='oakWaveTalk'?'oak':'resident',id);return}if(defenseActive()&&['hero','journal','map','villagers','bestiary','scout','night','build','buy','gift','demolishAsk','oakTalk','churchMemory','ritualMemory','repairObject','restoration','gather','stationGuards','domovoyTalk','sceneTime'].includes(action)){notify('Сначала отрази нападение. Меню и сохранения доступны.','error');return}if(action==='buy')window.storyAudio?.action('buy');const ui=game.ui,h=game.hero;switch(action){
case 'enter':go('menu');break;
case 'continue':{if(game.ui.ritualMemoryActive||game.ui.memoryActive||game.ui.oakActive||game.ui.waveTalk||defenseNovelActive()){go('novel');break}if(game.ui.sessionStarted){go(['game','chapter','novel','prologue'].includes(game.ui.resumeScreen)?game.ui.resumeScreen:'game');break}let available=game.saves.filter(Boolean).sort((a,b)=>b.timestamp-a.timestamp);if(available.length)loadSave(available[0].slotId);else notify('Нет сохранения');break}
case 'new':newGame();break;
case 'menu':go('menu');break;case 'rules':ui.rulesReturn='menu';go('rules');break;case 'rulesClose':go(ui.rulesReturn==='game'?'game':'menu');break;case 'savesClose':go(ui.savesReturn==='hero'?'hero':ui.savesReturn==='game'?'game':'menu');break;case 'scout':go('scout');break;case 'scoutPath':scoutPath(id);break;case 'threads':go('atlas');break;case 'chapterChoice':chooseChapter(id);break;case 'village':go('game');break;case 'hero':go('hero');break;case 'villagers':go('villagers');break;case 'bestiary':ui.heroTab='bestiary';go('hero');break;case 'saves':ui.savesReturn=game.screen;go('saves');break;
case 'settings':ui.settingsDraft=structuredClone(game.settings);ui.settingsDirty=false;ui.remap=null;go('settings');break;
case 'exit':modal('confirm',{title:'Покинуть Выселки?',text:'Можно вернуться к последней записи в Летописи.',confirm:'Уйти',cancel:'Остаться',onConfirm:'exit'});break;
case 'closeModal':closeModal();break;case 'confirm':confirmAction(ui.openModal);break;
case 'prologuePause':clearInterval(prologueTimer);prologueTimer=null;ui.prologuePaused=!ui.prologuePaused;render();break;
case 'prologueSkip':clearTimers();ui.novelIndex=0;ui.textShown=0;go('novel');break;
case 'prologueEnd':ui.novelIndex=0;ui.textShown=0;go('novel');break;
case 'prologueReplay':ui.prologueIndex=0;ui.prologueProgress=0;ui.prologuePaused=false;render();break;
case 'oakTalk':beginOakTalk();break;case 'oakReturn':finishOakTalk();break;case 'oakTopic':if(ui.oakActive&&OAK_TOPICS.some(t=>t.id===id)){ui.oakTopic=id;render();notify('Эта тема пока не открыта.','info')}break;case 'novelJournal':modal('novelJournal');break;case 'novelAuto':ui.novelAuto=!ui.novelAuto;render();break;case 'churchMemory':beginChurchMemory();break;case 'novelSkip':if(game.ui.ritualMemoryActive){game.ui.ritualMemoryIndex=game.ui.novelIndex;finishRitualMemory(false);break}if(game.ui.waveTalk){cancelWaveConversation();break}if(defenseNovelActive()){finishDefenseDialogue();break}if(ui.oakActive){finishOakTalk();break}if(ui.memoryActive){ui.memorySkipped=true;ui.novelIndex=novelLines().length-1;ui.memoryIndex=ui.novelIndex;ui.textShown=0;render();break}if(ui.novelChoice===null){ui.novelChoice='skipped';ui.novelHistory.push({speaker:'Рассказчик',text:'Влад вошёл в Выселки, не выбрав первый шаг.'})}enterVillage();break;case 'novelNext':nextNovel();break;
case 'novelChoice':{let i=Number(id);if(ui.ritualMemoryActive||ui.memoryActive||ui.novelIndex!==NOVEL_CHOICE_INDEX||!Number.isInteger(i)||i<0||i>=LINES[NOVEL_CHOICE_INDEX].choices.length)return;ui.novelChoice=i;ui.novelHistory.push({speaker:LINES[NOVEL_CHOICE_INDEX].speaker,text:LINES[NOVEL_CHOICE_INDEX].text});ui.novelHistory.push({speaker:'Выбор',text:LINES[NOVEL_CHOICE_INDEX].choices[i]});ui.novelIndex=NOVEL_CHOICE_INDEX+1;ui.textShown=0;render();break}
case 'questToggle':ui.questOpen=!ui.questOpen;render();break;
case 'trayToggle':ui.bottomPanelOpen=!ui.bottomPanelOpen;$('.bottom-tray')?.classList.toggle('collapsed',!ui.bottomPanelOpen);document.querySelectorAll('.tray-tabs,.tray-content').forEach(node=>node.inert=!ui.bottomPanelOpen);const toggle=$('[data-action=trayToggle]');if(toggle){toggle.innerHTML='<span>'+(ui.bottomPanelOpen?'Свернуть':'Развернуть')+'</span>'+brand(86);toggle.setAttribute('aria-expanded',String(ui.bottomPanelOpen))}saveLocal();break;case 'trayTab':ui.bottomTab='build';render();break;case 'build':{const b=BUILD.find(b=>b.id===id);if(!b||!canAfford(b.cost))break;ui.placing=id;ui.bottomPanelOpen=false;render();if(!window.village3D?.begin(id)){ui.placing=null;render();notify('3D-сцена недоступна','error')}break;}case 'placeConfirm':{const position=window.village3D?.confirm();if(position)build(position.id,position);else notify('Выбери свободный участок','error');break;}case 'placeCancel':window.village3D?.cancel();ui.placing=null;ui.bottomPanelOpen=true;render();break;case 'placeRotate':window.village3D?.rotate();break;case 'sceneZoomIn':window.village3D?.zoom(1.15);break;case 'sceneZoomOut':window.village3D?.zoom(.87);break;case 'sceneReset':window.village3D?.reset();break;case 'sceneTime':{const modes=['evening','night'];ui.sceneTime=modes[(modes.indexOf(ui.sceneTime||'evening')+1)%modes.length];render();break;}case 'demolishAsk':{const object=ui.openModal?.object,reason=(typeof restorationDemolitionReason==='function'?restorationDemolitionReason(object):null)||window.village3D?.demolitionReason(object);if(reason){notify(reason,'error');break}if(object)modal('confirm',{title:'Снести объект?',text:natureYield(object)?'После расчистки получишь: '+yieldLabel(natureYield(object))+'.':'Объект будет удалён с карты. Ресурсы не возвращаются.',confirm:natureYield(object)?'Расчистить':'Снести',onConfirm:'demolishObject',object});break;}case 'buy':buy(id);break;
case 'night':startNight();break;case 'nightChoice':chooseNight(Number(id));break;case 'dawn':dawn();break;case 'deathScreen':go('death');break;
case 'journal':go('diary');break;case 'map':go('atlas');break;case 'quick':modal('quick');break;case 'sound':game.settings.muted=!game.settings.muted;notify(game.settings.muted?'Звук выключен':'Звук включён');render();break;
case 'quickSave':game.ui.openModal=null;writeSave(game.ui.activeSaveSlot??game.ui.selectedSave??0);break;
case 'heroTab':ui.heroTab=id;render();break;case 'mapSelect':ui.mapSelection=id;render();break;case 'diaryPage':{let pages=diaryPages(),at=Math.max(0,pages.findIndex(p=>p.id===(ui.diarySelection||'night')));ui.diarySelection=pages[Math.max(0,Math.min(pages.length-1,at+Number(id)))].id;render();break}case 'diarySelectMemory':if(!memoryKnown()||!MEMORY_NOTES.some(n=>n.id===id))return;ui.diarySelection=id;go('diary');break;case 'diarySelect':if(!diaryPages().some(n=>n.id===id))return;ui.diarySelection=id;render();break;case 'openNote':ui.diarySelection='note:'+id;go('diary');break;case 'talk':talkToVillager(id);break;
case 'statPlus':if(h.statPoints>0&&h.stats[id]<10){h.stats[id]++;h.allocated[id]++;h.statPoints--;if(id==='end'){h.hpMax=3+Math.floor(h.stats.end/3);h.hp=Math.min(h.hpMax,h.hp+1)}render()}break;
case 'statMinus':if(h.allocated[id]>0){h.stats[id]--;h.allocated[id]--;h.statPoints++;if(id==='end'){h.hpMax=3+Math.floor(h.stats.end/3);h.hp=Math.min(h.hp,h.hpMax)}render()}break;
case 'resetStats':for(let k in h.allocated){h.stats[k]-=h.allocated[k];h.statPoints+=h.allocated[k];h.allocated[k]=0}h.hpMax=3+Math.floor(h.stats.end/3);h.hp=Math.min(h.hp,h.hpMax);render();break;
case 'selectSkill':ui.selectedSkill=id;render();break;case 'learnSkill':{let s=SKILLS.find(x=>x[0]===id);if(s&&!h.learnedSkills.includes(id)&&h.skillPoints>=s[2]){h.skillPoints-=s[2];h.learnedSkills.push(id);notify('Умение изучено: '+s[1]);render()}break}
case 'selectItem':ui.selectedItem=Number(id);render();break;case 'equip':{let b=h.bag[Number(id)];if(b?.slot){let old=h.equipment[b.slot];h.equipment[b.slot]=b.itemId;b.itemId=old;notify('Снаряжение надето');render()}break}
case 'useItem':{let b=h.bag[Number(id)];if(b?.use==='heal'&&b.qty>0&&h.hp<h.hpMax){const restored=Math.min(2,h.hpMax-h.hp);h.hp+=restored;b.qty--;if(!b.qty)h.bag.splice(Number(id),1);ui.selectedItem=Math.min(ui.selectedItem,h.bag.length-1);notify('Жизни +'+restored);render()}break}
case 'selectVillager':ui.selectedVillager=id;render();break;case 'job':{let v=game.villagers.find(x=>x.id===ui.selectedVillager);if(v&&v.alive!==false&&!v.fixedRole&&JOBS[id]){v.job=id==='none'?null:id;notify(`${v.name}: ${JOBS[id][0]}`);render()}break}
case 'gift':if(id==='porridge'&&game.resources.grain>=3&&game.domovoy.favour<100){game.resources.grain-=3;game.domovoy.favour=Math.min(100,game.domovoy.favour+15);notify('Домовой: благосклонность +15');render()}else if(id==='ribbon'&&game.resources.cloth>=1&&game.domovoy.favour<100){game.resources.cloth--;game.domovoy.favour=Math.min(100,game.domovoy.favour+30);notify('Домовой: благосклонность +30');render()}break;
case 'beastFilter':ui.beastFilter=id;ui.selectedBeast=(CREATURES.find(c=>id==='Все'||c.area===id||(id==='Болото'&&c.id==='kikimora'))||CREATURES[0]).id;render();break;case 'selectBeast':ui.selectedBeast=id;render();break;
case 'loadSave':loadSave(Number(id));break;
case 'writeSave':{let index=Number(id);if(!Number.isInteger(index)||index<0||index>2)break;ui.selectedSave=index;if(game.saves[index])modal('confirm',{title:'Перезаписать историю?',text:`Запись «${game.saves[index].name}» будет заменена текущей игрой.`,confirm:'Перезаписать',onConfirm:'overwrite',id:index,name:app.querySelector(`[data-save-name="${index}"]`)?.value});else writeSave(index);break}
case 'deleteSave':{let index=Number(id);if(game.saves[index])modal('confirm',{title:'Удалить историю?',text:`Запись «${game.saves[index].name}» будет удалена.`,confirm:'Удалить',onConfirm:'delete',id:index});break}
case 'settingsTab':ui.settingsTab=id;render();break;case 'settingsDefault':ui.settingsDraft=baseSettings();ui.settingsDirty=true;render();break;
case 'settingsApply':if(ui.settingsDraft){game.settings=structuredClone(ui.settingsDraft);ui.settingsDirty=false;if(game.settings.fullscreen&&!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>notify('Полный экран недоступен'));if(!game.settings.fullscreen&&document.fullscreenElement)document.exitFullscreen?.();notify('Настройки применены');render()}break;
case 'remap':ui.remap=id;render();break;
}}
app.addEventListener('pointermove',e=>{let panel=e.target.closest('.dialogue-box,.modal');if(!panel)return;let r=panel.getBoundingClientRect();panel.style.setProperty('--light-x',((e.clientX-r.left)/r.width*100).toFixed(1)+'%');panel.style.setProperty('--light-y',((e.clientY-r.top)/r.height*100).toFixed(1)+'%')});
app.addEventListener('pointerover',e=>{const target=e.target.closest('button');if(target&&!target.disabled&&!target.contains(e.relatedTarget))window.storyAudio?.hover();const b=e.target.closest('.chapter-options .option');if(b&&!b.contains(e.relatedTarget))window.storyCharms?.choose(b)});app.addEventListener('click',e=>{if(screenTransition)return;let b=e.target.closest('[data-action]');if(!b||b.disabled)return;playUiTone(['novelChoice','nightChoice'].includes(b.dataset.action)?'choice':b.dataset.action==='build'?'build':'tap');handleAction(b.dataset.action,b.dataset.id,b)});
app.addEventListener('input',e=>{const s=e.target.dataset.setting,q=e.target.dataset.quick;if(s){game.ui.settingsDraft??=structuredClone(game.settings);game.ui.settingsDraft[s]=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;game.ui.settingsDirty=true;const v=e.target.parentElement.querySelector('.small');if(v&&e.target.type==='range')v.textContent=e.target.value;saveLocal()}if(q){game.settings[q]=Number(e.target.value);window.storyAudio?.sync(game);saveLocal()}});
app.addEventListener('change',e=>{if(e.target.dataset.setting)render();const index=e.target.dataset.saveName;if(index!==undefined&&game.saves[Number(index)]){game.saves[Number(index)].name=e.target.value.trim().slice(0,48)||`Выселки · День ${game.saves[Number(index)].day}`;e.target.value=game.saves[Number(index)].name;saveLocal();notify('Название изменено')}});
document.addEventListener('keydown',e=>{
 if(screenTransition)return;
 if(game.ui.remap){e.preventDefault();let target=game.ui.remap,keys=game.ui.settingsDraft.keys,key=e.key;if(['Escape','Tab','Shift','Control','Alt','Meta','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key)||/^[1-6+\-=]$/.test(key)||key==='Enter'){notify('Эта клавиша зарезервирована');return}if(Object.entries(keys).some(([k,v])=>k!==target&&v.toLowerCase()===key.toLowerCase())){notify('Клавиша уже занята');return}keys[target]=key;game.ui.remap=null;game.ui.settingsDirty=true;render();return}
 if(e.target.closest?.('input,textarea,select,[contenteditable]'))return;if(game.screen==='game'&&game.ui.oakEncounterActive){if(['Enter',' ','Escape'].includes(e.key)){e.preventDefault();e.key==='Escape'?endOakEncounter():nextOakEncounter()}return;}
 if(game.screen==='game'&&!game.ui.openModal&&defenseActive()&&[' ','h','H','р','Р','f','F','а','А'].includes(e.key)){e.preventDefault();handleDefenseAction(e.key===' '?'defenseAttack':['f','F','а','А'].includes(e.key)?'defenseFlash':'defenseHeal');return}
 if(game.screen==='game'&&game.ui.placing){if(e.key==='Escape'){e.preventDefault();handleAction('placeCancel')}else if(e.key.toLowerCase()==='r'||e.key.toLowerCase()==='к'){e.preventDefault();handleAction('placeRotate')}else if(e.key==='Enter'){e.preventDefault();handleAction('placeConfirm')}return}
 if(e.key==='Escape'&&game.ui.waveTalk){e.preventDefault();cancelWaveConversation();return}if(e.key==='Escape'&&game.ui.oakActive){e.preventDefault();finishOakTalk();return}if(e.key==='Escape'){if(game.ui.openModal)closeModal();else if(game.screen==='game')modal('quick');else if(!['loading','menu'].includes(game.screen))go('menu');return}
 if(game.ui.openModal)return;
 if(game.screen==='novel'){
   if(!game.ui.ritualMemoryActive&&!game.ui.memoryActive&&!game.ui.oakActive&&!game.ui.waveTalk&&!defenseNovelActive()&&['1','2','3'].includes(e.key)&&game.ui.novelIndex===NOVEL_CHOICE_INDEX&&game.ui.novelChoice===null){e.preventDefault();handleAction('novelChoice',String(Number(e.key)-1));return}
   if(e.key==='Enter'||e.key===' '){e.preventDefault();nextNovel()}return;
 }
 if(game.screen==='diary'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();handleAction('diaryPage',e.key==='ArrowLeft'?'-1':'1');return}
 if(game.screen==='atlas'&&['1','2','3','4'].includes(e.key)){e.preventDefault();handleAction('mapSelect',['village','forest','marsh','ruins'][Number(e.key)-1]);return}
 if(game.screen==='hero'&&['1','2','3','4'].includes(e.key)){e.preventDefault();handleAction('heroTab',['stats','equipment','bestiary','chronicle'][Number(e.key)-1]);return}
 if(game.screen!=='game')return;
 if(e.key==='+'||e.key==='='){e.preventDefault();handleAction('sceneZoomIn');return}if(e.key==='-'){e.preventDefault();handleAction('sceneZoomOut');return}
 if(/^[1-6]$/.test(e.key)&&game.ui.bottomPanelOpen&&!defenseActive()){let index=Number(e.key)-1,item=(game.ui.bottomTab!=='market'?BUILD:MARKET)[index];if(item){e.preventDefault();if(game.ui.bottomTab==='build'?canAfford(item.cost):game.resources.silver>=item.price)handleAction(game.ui.bottomTab==='build'?'build':'buy',item.id);return}}
 const key=e.key.toLowerCase(), action=Object.entries(game.settings.keys).find(([,v])=>v.toLowerCase()===key)?.[0];
 if(!action)return;e.preventDefault();
 if(action==='night')startNight();else if(action==='quickSave')writeSave(game.ui.activeSaveSlot??game.ui.selectedSave??0);else if(action==='tray')handleAction('trayToggle');else if(action==='settings')handleAction('quick');else if(action==='menu')modal('quick');else if(['journal','map','hero','villagers','bestiary','scout','sound','saves'].includes(action))handleAction(action);
});
render();

window.addEventListener('pagehide',saveLocal);
